let data=null, session=null, stateVersion=0, saveChain=Promise.resolve();
let salesDirectory=[];
let userDirectory=[];
function clone(x){return JSON.parse(JSON.stringify(x))}
async function apiCall(path,options={}){const r=await fetch(path,{credentials:'same-origin',...options,headers:{...(options.body instanceof FormData?{}:{'content-type':'application/json'}),...(options.headers||{})}});let b=null;try{b=await r.json()}catch{}if(!r.ok){const msg=b?.error==='INTERNAL_ERROR'&&b?.message?`${b.error}: ${b.message}`:(b?.error||`HTTP ${r.status}`);const e=new Error(msg);e.status=r.status;e.payload=b;throw e}return b}
async function fetchState(){const r=await apiCall('/api/state');data=r.data;stateVersion=r.version;return data}
function save(){const snapshot=clone(data);saveChain=saveChain.then(async()=>{try{const r=await apiCall('/api/state',{method:'PUT',body:JSON.stringify({version:stateVersion,data:snapshot})});stateVersion=r.version}catch(e){if(e.status===409){alert('Data berubah dari perangkat lain. RMS akan memuat ulang data terbaru.');await fetchState();render()}else{console.error('Gagal menyimpan RMS',e);alert('Gagal menyimpan ke database Cloudflare. Periksa koneksi lalu coba lagi.')}}});return saveChain}
async function uploadFile(file,entityType,entityId){if(!file)return null;const fd=new FormData();fd.append('file',file);fd.append('entityType',entityType);fd.append('entityId',entityId||'');return apiCall('/api/files',{method:'POST',body:fd})}
function fileUrl(id,download=false){return id?`/api/files/${encodeURIComponent(id)}${download?'?download=1':''}`:''}
async function removeFile(id){if(!id)return;return apiCall('/api/files/'+encodeURIComponent(id),{method:'DELETE'})}
async function boot(){try{const me=await apiCall('/api/auth/me');if(!me||!me.user){throw new Error('Session user tidak ditemukan')}session={id:me.user.id,role:me.user.role,name:me.user.name,email:me.user.email,scopeName:me.user.scopeName||me.user.name,mustChangePassword:me.user.mustChangePassword};try{const d=await apiCall('/api/directory/sales');salesDirectory=d.sales||[]}catch{salesDirectory=[]}try{const d=await apiCall('/api/directory/users');userDirectory=d.users||[]}catch{userDirectory=[]}await fetchState();try{render()}catch(err){document.getElementById('root').innerHTML=`<div class="login"><h2>RMS mengalami error tampilan</h2><p>${esc(err.message)}</p><button onclick="location.reload()">Refresh</button></div>`}}catch(e){session=null;data=null;salesDirectory=[];userDirectory=[];login()}}
function uid(p){return `${p}-${Date.now().toString(36).toUpperCase()}`}
function esc(s=''){return String(s).replace(/[&<>'"]/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#039;','"':'&quot;'}[m]))}
function money(n){return new Intl.NumberFormat('id-ID',{style:'currency',currency:'IDR',maximumFractionDigits:0}).format(Number(n)||0)}
function num(n){return new Intl.NumberFormat('id-ID').format(Number(n)||0)}
function leadForecastValue(l){const asst=Number(l?.estAsstCr||0),rab=Number(l?.estRab||0);return asst>0?asst:(rab>0?rab:0)}
function pct(n){return `${Number(n)||0}%`}
function date(s){if(!s)return'-';return new Date(s+'T00:00:00').toLocaleDateString('id-ID',{day:'2-digit',month:'short',year:'numeric'})}
function nowLabel(){return '10 Aug 2026 • '+new Date().toLocaleTimeString('id-ID',{hour:'2-digit',minute:'2-digit'})}
function badge(status){let s=String(status||'-'),tone='neutral';if(['VERIFIED','PAID','APPROVED','SIGNED','COMPLETED','CLOSED','SELESAI','DONE','ACCEPTED','FINAL','PASS'].includes(s))tone='success';else if(['PENDING_VERIFICATION','PARTIAL','ON_PROGRESS','WAITING_VERIFICATION','DUE','HOT','DP_PROYEK','DP_GAMBAR','RECEIVED','SUBMITTED','PENDING'].includes(s))tone='warning';else if(['OVERDUE','REJECTED','CRITICAL','BATAL','HOLD_BATAL','NEED_REVISION','MISSING','RETURNED'].includes(s))tone='danger';else if(['RUNNING','PEMBANGUNAN','FINDING_CREATED'].includes(s))tone='info';return `<span class="badge ${tone}">${esc(s.replaceAll('_',' '))}</span>`}
function pageHead(title,desc,action=''){return `<div class="pagehead"><div><div class="eyebrow">RUMSY INTERNAL • PRODUCTION</div><h1>${title}</h1>${desc?`<p>${desc}</p>`:''}</div>${action}</div>`}
function stat(label,value,tone='',sub=''){return `<div class="stat"><div class="stat-label">${label}</div><div class="stat-value ${tone}">${value}</div>${sub?`<div class="stat-sub">${sub}</div>`:''}</div>`}
function card(title,body,action=''){return `<section class="card"><div class="card-head"><h3>${title}</h3>${action}</div><div class="card-body">${body}</div></section>`}
function info(label,val){return `<div class="info"><label>${label}</label><div>${val}</div></div>`}

// FIX73 USER ACCESS OVERRIDE
function getUserOverride(userId){
  let u=(data.userAccessOverrides||[]).find(x=>String(x.userId)===String(userId));
  return u||{add:[],remove:[]};
}
function hasCustomPermission(permission,userId=session.id){
  let o=getUserOverride(userId);
  if((o.remove||[]).includes(permission)) return false;
  return (o.add||[]).includes(permission);
}
function normSales(s=''){return String(s).trim().toLowerCase().replace(/\s+/g,' ')}
function salesDisplay(x){return String(x?.scopeName||x?.scope_name||x?.name||x?.full_name||'').trim()}
function salesDirectoryNames(){return [...new Set((salesDirectory||[]).map(salesDisplay).filter(Boolean))]}
function salesIdentityKeys(){let a=[session?.scopeName,session?.name,(session?.email||'').split('@')[0]].filter(Boolean).map(normSales);return [...new Set(a)]}
function belongsToSales(value){let v=normSales(value),keys=salesIdentityKeys();return !!v&&keys.some(k=>v===k||v.includes(k)||k.includes(v))}
function visibleLeads(){return session?.role==='SALES_EXECUTIVE'?data.leads.filter(l=>belongsToSales(l.sales)):data.leads}
function visibleProjects(){return session?.role==='SALES_EXECUTIVE'?data.projects.filter(p=>belongsToSales(p.sales)):session?.role==='QC_TEKNIS'?data.projects.filter(p=>p.qc):data.projects}
function currentContract(p){return p.originalContract+p.addendums.filter(a=>['APPROVED','SIGNED'].includes(a.status)).reduce((s,a)=>s+Number(a.value||0),0)}
function verifiedPaid(p){return p.transactions.filter(t=>t.status==='VERIFIED').reduce((s,t)=>s+Number(t.amount||0),0)}
function installmentPaid(p,ins){return p.transactions.filter(t=>t.installmentId===ins.id&&t.status==='VERIFIED').reduce((s,t)=>s+Number(t.amount||0),0)}
function installmentStatus(p,ins){let paid=installmentPaid(p,ins),due=Number(ins.dueAmount);if(paid>=due)return'PAID';if(paid>0)return ins.due<TODAY?'OVERDUE':'PARTIAL';if(ins.due<TODAY)return'OVERDUE';if(ins.due===TODAY)return'DUE';return'UPCOMING'}
function allTransactions(){return data.projects.flatMap(p=>p.transactions.map(t=>({...t,projectId:p.id,projectName:p.name,client:p.client})))}
function allFindings(){return data.projects.flatMap(p=>p.qcFindings.map(q=>({...q,projectId:p.id,projectName:p.name})))}
function allInspections(){return data.projects.flatMap(p=>p.inspections.map(i=>({...i,projectId:p.id,projectName:p.name})))}
function metrics(){let ps=visibleProjects(),trs=ps.flatMap(p=>p.transactions),contract=ps.reduce((s,p)=>s+currentContract(p),0),paid=trs.filter(t=>t.status==='VERIFIED').reduce((s,t)=>s+Number(t.amount),0),q=ps.flatMap(p=>p.qcFindings);return{projects:ps.length,active:ps.filter(p=>p.status!=='COMPLETED').length,contract,paid,outstanding:contract-paid,pending:trs.filter(t=>t.status==='PENDING_VERIFICATION').length,qc:q.filter(x=>x.status!=='CLOSED').length,qcOver:q.filter(x=>x.status==='OVERDUE').length,follow:visibleLeads().filter(l=>l.nextFollowUp&&l.nextFollowUp<=TODAY&& !['SELESAI','HOLD_BATAL'].includes(l.stage)).length}}
function addAudit(actor,entity,entityId,action,detail){data.audit.unshift({at:'2026-08-10 '+new Date().toLocaleTimeString('en-GB',{hour:'2-digit',minute:'2-digit'}),actor,entity,entityId,action,detail})}
function addProjectActivity(p,actor,text){p.activity.unshift({at:nowLabel(),actor,text})}
function leadById(id){return data.leads.find(l=>l.id===id)}
function projectById(id){return data.projects.find(p=>p.id===id)}
const HOT_MILESTONES=['Survey selesai','Proposal/RAB dikirim','Meeting penawaran selesai'];
function projectForLead(id){return data.projects.find(p=>p.leadId===id)}
function hotQualification(l){return{need:!!String(l.need||'').trim(),location:!!String(l.location||'').trim(),estRab:Number(l.estRab||0)>0,sales:!!String(l.sales||'').trim(),nextAction:!!String(l.nextFollowUp||'').trim(),milestone:(l.milestones||[]).some(x=>HOT_MILESTONES.includes(x))}}
function finalQcReady(p){return (p.qcFindings||[]).every(q=>q.status==='CLOSED')}
function hasFinalBast(p){return (p.documents||[]).some(d=>d.type==='BAST'&&d.status==='FINAL'&&d.name)}
function derivePipelineStage(l,p=projectForLead(l.id)){
  if(!l)return'WARM';
  if(l.pipelineSide||l.stage==='HOLD_BATAL')return'HOLD_BATAL';
  if(p){
    const dpG=(p.transactions||[]).some(t=>t.type==='DP_GAMBAR'&&t.status==='VERIFIED');
    const dpP=(p.transactions||[]).some(t=>t.type==='DP_PROYEK'&&t.status==='VERIFIED');
    if(p.completionApproved&&Number(p.progress)>=100&&hasFinalBast(p)&&finalQcReady(p))return'SELESAI';
    if(p.started&&p.handover?.status==='ACCEPTED'&&p.contract?.status==='SIGNED'&&dpP)return'PEMBANGUNAN';
    if(dpP)return'DP_PROYEK';
    if(dpG)return'DP_GAMBAR';
  }else if(['DP_GAMBAR','DP_PROYEK','PEMBANGUNAN','SELESAI'].includes(l.stage)){
    // Seed demo lama dipertahankan sebagai contoh visual jika belum mempunyai dossier Project.
    return l.stage;
  }
  const q=hotQualification(l);
  return(q.need&&q.location&&q.estRab&&q.sales&&q.nextAction&&q.milestone)?'HOT':'WARM';
}
function recomputeLeadStage(l,withAudit=true){if(!l)return false;let target=derivePipelineStage(l),prev=l.stage;if(prev===target)return false;l.stage=target;if(withAudit){addAudit('System','PIPELINE',l.id,'AUTO_MOVE',`${prev} → ${target} berdasarkan milestone/event tervalidasi`);addLeadChat(l,'System',`Pipeline otomatis berubah ${stageNames[prev]||prev} → ${stageNames[target]||target}.`,true)}return true}
function normalizeLeadStages(){let changed=false;data.leads.forEach(l=>{if(recomputeLeadStage(l,false))changed=true});if(changed)save()}
function syncPipelineForProject(p){let l=leadById(p.leadId);if(!l)return false;return recomputeLeadStage(l,true)}
function stagePath(l){return `<div class="stage-path">${stages.map(s=>`<span class="stage-step ${s===l.stage?'current':stages.indexOf(s)<stages.indexOf(l.stage)?'done':''}">${stageNames[s]}</span>`).join('')}</div>`}
