function userByName(name){let n=String(name||'').trim().toLowerCase();return userDirectory.find(u=>String(u.name||'').trim().toLowerCase()===n||String(u.scopeName||'').trim().toLowerCase()===n)}
function userOptions(selected='',filterRoles=null){let list=userDirectory.filter(u=>!filterRoles||filterRoles.includes(u.role));return `<option value="">- Pilih PIC -</option>`+list.map(u=>`<option value="${u.id}" ${String(selected)===String(u.id)?'selected':''}>${esc(u.name)} • ${esc(roles[u.role]||u.role)} • ${esc(u.email)}</option>`).join('')}
function supervisorRole(role){return ({SALES_EXECUTIVE:'MANAGER_SALES',ADMIN_CRM:'MANAGER_SALES',QC_TEKNIS:'MANAGER_QC',MANAGER_OPERASIONAL:'HEAD_BU',MANAGER_SALES:'HEAD_BU',MANAGER_QC:'HEAD_BU',ADMIN_GENERAL:'HEAD_BU',HEAD_BU:'SUPER_ADMIN',HOLDING_FINANCE:'HEAD_BU',HOLDING_PURCHASING:'HEAD_BU',HOLDING_HRD:'HEAD_BU',HOLDING_LEGAL:'HEAD_BU',HOLDING_ARDA:'HEAD_BU',SUPER_ADMIN:'HEAD_BU'})[role]||'HEAD_BU'}
