async function sendTaskEmail(kind,t,toUserId){try{let r=await apiCall('/api/notify/task',{method:'POST',body:JSON.stringify({kind,toUserId,task:{id:t.id,title:t.title,projectId:t.projectId||'',description:t.description||'',startDate:t.startDate||'',due:t.due||'',status:t.status||'',reviewNote:t.reviewNote||'',creator:t.creator||'',pic:t.pic||'',reviewerName:t.reviewerName||''}})});t.emailStatus=r.sent?'SENT':(r.reason||'NOT_SENT');return r}catch(e){t.emailStatus='ERROR';console.warn('Email task gagal',e);return {sent:false,reason:e.message}}}
