async function deleteLead(l,after){if(!l||!canDeleteLead(l))return alert('Anda tidak memiliki akses untuk menghapus Lead.');let linked=projectForLead(l.id);if(linked)return alert(`Lead ini sudah terhubung ke Project ${linked.id} dan tidak boleh dihapus. Gunakan status Hold/Batal agar riwayat tetap aman.`);if(!confirm(`Hapus Lead ${l.client}? Data Lead dan chat internalnya akan dihapus permanen.`))return;data.leads=data.leads.filter(x=>x.id!==l.id);addAudit(currentActor(),'LEAD',l.id,'DELETE',`Lead ${l.client} dihapus`);await save();if(typeof after==='function')after();else{location.hash='#/leads';route()}}
