function ensureDataShape(){data.correspondence??=[];data.salesDailyReports??=[];data.leads??=[];data.clients??=[];data.projects??=[];data.tasks??=[];data.leads.forEach(l=>{l.milestones??=[];l.chat??=[{id:uid('CHAT'),actor:'System',role:'SYSTEM',text:`Thread internal lead ${l.client} aktif.`,attachment:'',at:'System',system:true}];l.pipelineSide??='';l.previousStage??=''});data.projects.forEach(p=>{p.transactions??=[];p.installments??=[];p.addendums??=[];p.documents??=[];p.inspections??=[];p.qcFindings??=[];p.activity??=[];p.progressDaily??=[];p.progressWeekly??=[];p.clientPortal??={enabled:false,token:'',createdAt:''};p.chat??=[{id:uid('CHAT'),actor:'System',role:'SYSTEM',text:`Thread internal project ${p.id} aktif.`,attachment:'',at:'System',system:true}];p.handover??={status:'DRAFT',submittedAt:'',reviewedAt:'',note:''};p.contract??={number:'',date:'',status:'DRAFT',dp:0,margin:0,tenor:0};p.targetFinish??='';p.startDate??='';p.ops??='Manager Operasional';p.qc??='QC Teknis';if(!p.opsUserId){let u=userByName(p.ops);if(u)p.opsUserId=u.id}if(!p.qcUserId){let u=userByName(p.qc);if(u)p.qcUserId=u.id}if(!p.salesUserId){let u=userByName(p.sales);if(u)p.salesUserId=u.id}});data.tasks.forEach(t=>{t.description??='';t.startDate??='';t.due??='';t.submittedAt??='';t.completedAt??='';t.reviewNote??='';t.revisionCount??=0;t.emailStatus??='';if(!t.picUserId){let u=userByName(t.pic);if(u)t.picUserId=u.id}if(!t.reviewerUserId&&t.picUserId){let r=suggestedReviewer(t.picUserId);if(r){t.reviewerUserId=r.id;t.reviewerName=r.name}}})}
