function ensureProjectForLead(l){let p=projectForLead(l.id);if(p)return p;let c=ensureClientForLead(l);p={id:`RMS-PRJ-${new Date().getFullYear()}-${Date.now().toString(36).toUpperCase()}`,clientId:c.id,leadId:l.id,name:`${l.need} - ${l.client}`,client:l.client,location:l.location,sales:l.sales,salesUserId:(userByName(l.sales)?.id||''),ops:'Manager Operasional',opsUserId:(userDirectory.find(u=>u.role==='MANAGER_OPERASIONAL')?.id||''),qc:'QC Teknis',qcUserId:(userDirectory.find(u=>u.role==='QC_TEKNIS')?.id||''),status:'PREPARATION',progress:0,originalContract:Number(l.estRab||0),startDate:'',targetFinish:'',actualFinish:'',contract:{number:'',date:TODAY,status:'DRAFT',dp:Number(l.dp||0),margin:Number(l.margin||0),tenor:36},handover:{status:'DRAFT',submittedAt:'',reviewedAt:'',note:''},started:false,completionApproved:false,transactions:[],installments:[],addendums:[],documents:[],inspections:[],qcFindings:[],progressDaily:[],progressWeekly:[],clientPortal:{enabled:false,token:'',createdAt:''},activity:[],chat:[]};data.projects.unshift(p);addProjectActivity(p,currentActor(),`Dossier project dibuat otomatis dari ${l.id}.`);addProjectChat(p,'System',`Project dossier dibuat dari lead ${l.client}.`,true);addLeadChat(l,'System',`Project dossier ${p.id} dibuat dan ditautkan ke lead.`,true);addAudit(currentActor(),'PROJECT',p.id,'CREATE_FROM_LEAD',`Dibuat dari ${l.id}`);save();return p}
function nextStageInfo(l){let p=projectForLead(l.id);if(l.stage==='WARM'){let q=hotQualification(l),missing=[!q.need&&'kebutuhan',!q.location&&'lokasi',!q.estRab&&'Est. RAB',!q.sales&&'Sales PIC',!q.nextAction&&'next follow-up',!q.milestone&&'milestone Survey/Proposal/Meeting'].filter(Boolean);return{next:'HOT',text:missing.length?`Lengkapi: ${missing.join(', ')}`:'Qualification siap dievaluasi'}}if(l.stage==='HOT'){let pending=p?.transactions?.find(t=>['DP_GAMBAR','DP_PROYEK'].includes(t.type)&&t.status==='PENDING_VERIFICATION');return{next:pending?.type==='DP_PROYEK'?'DP PROYEK':'DP GAMBAR / DP PROYEK',text:pending?`${pending.label} menunggu verifikasi Finance`:'Upload bukti DP lalu Finance melakukan verifikasi'}}if(l.stage==='DP_GAMBAR'){let pending=p?.transactions?.find(t=>t.type==='DP_PROYEK'&&t.status==='PENDING_VERIFICATION');return{next:'DP PROYEK',text:pending?'DP Proyek menunggu verifikasi Finance':'Upload bukti DP Proyek lalu Finance verifikasi'}}if(l.stage==='DP_PROYEK'){if(!p)return{next:'PEMBANGUNAN',text:'Tautkan/buka Project dossier'};let miss=[p.contract.status!=='SIGNED'&&'Contract SIGNED',p.handover.status!=='ACCEPTED'&&'Handover ACCEPTED',!p.started&&'Project Start APPROVED'].filter(Boolean);return{next:'PEMBANGUNAN',text:miss.length?`Menunggu: ${miss.join(', ')}`:'Start gate lengkap'}}if(l.stage==='PEMBANGUNAN'){if(!p)return{next:'SELESAI',text:'Project dossier belum tersedia'};let miss=[Number(p.progress)<100&&'Progress 100%',!finalQcReady(p)&&'Final QC Closed',!hasFinalBast(p)&&'BAST FINAL',!p.completionApproved&&'Completion Approval'].filter(Boolean);return{next:'SELESAI',text:miss.length?`Menunggu: ${miss.join(', ')}`:'Completion gate lengkap'}}if(l.stage==='HOLD_BATAL')return{next:'-',text:`${l.pipelineSide||'HOLD/BATAL'}: ${l.sideReason||'-'}`};return{next:'-',text:'Pipeline selesai'}}
function chatBox(messages,formId,title='Chat Internal'){return `<div class="chat-box"><div class="chat-title"><b>${title}</b><span class="tiny muted">Internal • tersimpan di Cloudflare</span></div><div class="chat-messages">${messages.map(m=>`<div class="chat-msg ${m.system?'system':''}"><div class="chat-meta"><b>${esc(m.actor)}</b><span>${esc(m.at||'')}</span></div><div>${esc(m.text)}</div>${m.attachment?`<div class="chat-attachment">📎 ${m.attachmentFileId?`<a class="link" target="_blank" href="${fileUrl(m.attachmentFileId)}">${esc(m.attachment)}</a>`:esc(m.attachment)}</div>`:''}</div>`).join('')||'<div class="empty">Belum ada pesan.</div>'}</div><form id="${formId}" class="chat-form"><textarea class="input" name="message" rows="2" placeholder="Tulis pesan internal..." required></textarea><div class="chat-actions"><input type="file" class="input" name="attachment"><button class="btn primary">Kirim</button></div></form></div>`}

function login(){document.getElementById('root').innerHTML=`<div class="login"><div class="login-left"><div class="login-brand"><img src="./rms-mark.svg"><div><b>RUMSY</b><small>INTERNAL MANAGEMENT SYSTEM</small></div></div><div class="login-copy"><div class="tag">PRODUCTION • CLOUDFLARE</div><h1>Masuk ke RMS.</h1><p>Sistem internal Rumsy menggunakan Cloudflare Workers, D1 Database dan private R2 Storage.</p></div><div class="login-foot">Data tersimpan terpusat di Cloudflare</div></div><div class="login-right"><div class="login-card"><span class="badge info">RMS PRODUCTION</span><h2>Login RMS</h2><p>Masukkan akun internal yang dibuat oleh Super Admin.</p><form id="loginForm"><label class="field"><span>EMAIL</span><input class="input" id="loginEmail" type="email" autocomplete="username" required></label><label class="field"><span>PASSWORD</span><input class="input" id="loginPassword" type="password" autocomplete="current-password" required></label><button class="btn primary" style="width:100%;padding:12px">Masuk →</button><div id="loginError" class="login-error"></div></form></div></div></div>`;$('#loginForm').onsubmit=async e=>{e.preventDefault();$('#loginError').textContent='';const btn=e.target.querySelector('button');btn.disabled=true;btn.textContent='Memproses...';try{const r=await apiCall('/api/auth/login',{method:'POST',body:JSON.stringify({email:$('#loginEmail').value.trim(),password:$('#loginPassword').value})});session={id:r.user.id,role:r.user.role,name:r.user.name,email:r.user.email,scopeName:r.user.scopeName||r.user.name,mustChangePassword:r.user.mustChangePassword};try{const d=await apiCall('/api/directory/sales');salesDirectory=d.sales||[]}catch{salesDirectory=[]}try{const d=await apiCall('/api/directory/users');userDirectory=d.users||[]}catch{userDirectory=[]}await fetchState();render();if(session.mustChangePassword)setTimeout(()=>openPasswordModal(true),200)}catch(err){$('#loginError').textContent=err.message||'Login gagal.'}finally{btn.disabled=false;btn.textContent='Masuk →'}}}
function canSee(item){return item.roles.includes(session.role)}
function shell(){let items=nav.filter(canSee),grouped={};items.forEach(x=>(grouped[x.section]??=[]).push(x));return `<div class="mobile-overlay" id="overlay"></div><div class="app"><aside class="sidebar" id="sidebar"><div class="brand"><img src="./rms-mark.svg"><div><b>RMS <span class="demo-pill">LIVE</span></b><small>Rumsy Internal System</small></div></div><nav class="nav">${Object.entries(grouped).map(([s,arr])=>`${s?`<div class="nav-title">${s}</div>`:''}${arr.map(x=>`<a href="#/${x.route}" data-route="${x.route}"><span class="nav-icon">${x.icon}</span>${x.label}</a>`).join('')}`).join('')}</nav><div class="role-card"><div class="role-inner"><small>Pengguna aktif</small><b id="roleText">${esc(session.name)}</b><span class="tiny">${roles[session.role]}</span></div></div></aside><main class="main"><header class="topbar"><button class="hamb icon-btn" id="hamb">☰</button><div class="search">⌕ <input id="globalSearch" placeholder="Cari client / project / transaksi..."></div><div class="spacer"></div><button class="user-chip" id="userMenu"><b>${esc(session.name)}</b><small>${roles[session.role]}</small></button><button class="icon-btn" id="notifBtn">♢<span class="dot"></span></button><button class="icon-btn" id="logout" title="Keluar">⇥</button></header><section class="content"><div class="page" id="view"></div></section></main></div>`}
function parseRoute(){let h=location.hash.replace(/^#\/?/,'');if(!h)return{page:'dashboard'};let a=h.split('/');if(a[0]==='projects'&&a[1])return{page:'project',id:decodeURIComponent(a[1]),tab:a[2]||'overview'};if(a[0]==='leads'&&a[1])return{page:'lead-detail',id:decodeURIComponent(a[1])};if(a[0]==='clients'&&a[1])return{page:'client-detail',id:decodeURIComponent(a[1])};return{page:a[0]}}
function render(){if(!session)return login();ensureDataShape();$('#root').innerHTML=shell();$('#hamb').onclick=()=>{$('#sidebar').classList.add('open');$('#overlay').classList.add('open')};$$('.nav a[data-route="project-dashboard"]').forEach(a=>a.onclick=e=>{e.preventDefault();if(location.hash!=='#/project-dashboard')location.hash='#/project-dashboard';route()});$('#overlay').onclick=()=>{$('#sidebar').classList.remove('open');$('#overlay').classList.remove('open')};$('#logout').onclick=async()=>{try{await apiCall('/api/auth/logout',{method:'POST',body:'{}'})}catch{}session=null;data=null;login()};$('#userMenu').onclick=()=>openModal('Akun Aktif',`<div class="grid2eq">${info('Nama',esc(session.name))}${info('Email',esc(session.email||'-'))}${info('Role',roles[session.role])}${info('Backend','Cloudflare D1 + R2')}</div><button class="btn ghost" id="changePassword" style="width:100%;margin-top:14px">Ganti Password</button><button class="btn ghost" id="switchAccount" style="width:100%;margin-top:8px">Keluar & Ganti Akun</button>`,()=>{$('#changePassword').onclick=()=>{closeModal();openPasswordModal(false)};$('#switchAccount').onclick=async()=>{closeModal();try{await apiCall('/api/auth/logout',{method:'POST',body:'{}'})}catch{}session=null;data=null;login()}});$('#notifBtn').onclick=()=>location.hash='#/notifications';$('#globalSearch').onkeydown=e=>{if(e.key==='Enter'&&e.target.value.trim())globalSearch(e.target.value.trim())};window.onhashchange=route;route()}
function route(){normalizeLeadStages();let r=parseRoute(),linkPage=r.page==='project'?'projects':r.page==='lead-detail'?'leads':r.page==='client-detail'?'clients':r.page;$$('.nav a').forEach(a=>a.classList.toggle('active',a.dataset.route===linkPage));let item=nav.find(x=>x.route===linkPage);if(item&&!canSee(item)){return forbidden($('#view'))}let fn={dashboard,salesDashboard,leads,leadDetail,pipeline,kanban,forecast,activity,salesDailyReport,clients,clientDetail,projects,projectsActive,projectsCompleted,projectDashboard,handover,project,correspondence,financeVerification,financeSchedule,financeLedger,financeOutstanding,qc,qcInspection,qcFindings,qcCorrective,qcEscalation,tasks,approvals,support,guide,reports,notifications,organization,audit,userAccess,systemCheck,emailNotification,settings}[camel(r.page)]||dashboard;fn($('#view'),r)}
function camel(s){return s.replace(/-([a-z])/g,(_,c)=>c.toUpperCase())}
function forbidden(v){v.innerHTML=pageHead('Akses dibatasi','Role ini tidak memiliki akses ke modul tersebut.')+card('403','<div class="empty">Ganti role di kanan atas atau kembali ke Dashboard.</div>')}
function globalSearch(q){q=q.toLowerCase();let l=data.leads.filter(x=>(x.client+x.phone+x.location).toLowerCase().includes(q)),p=data.projects.filter(x=>(x.id+x.name+x.client).toLowerCase().includes(q)),t=allTransactions().filter(x=>(x.id+x.projectId+x.proofName).toLowerCase().includes(q));openModal('Global Search',`${l.length?'<h4>Lead/Client</h4>'+l.map(x=>`<div class="doc-item"><div><b>${x.client}</b><div class="tiny muted">${x.phone} • ${x.location}</div></div><a class="btn ghost small" href="#/leads/${x.id}" onclick="closeModal()">Buka</a></div>`).join(''):''}${p.length?'<h4>Project</h4>'+p.map(x=>`<div class="doc-item"><div><b>${x.id}</b><div class="tiny muted">${x.name}</div></div><a class="btn ghost small" href="#/projects/${x.id}" onclick="closeModal()">Buka</a></div>`).join(''):''}${t.length?'<h4>Transaction</h4>'+t.map(x=>`<div class="doc-item"><div><b>${x.id} • ${x.label}</b><div class="tiny muted">${x.projectId} • ${money(x.amount)}</div></div><a class="btn ghost small" href="#/projects/${x.projectId}/transaction" onclick="closeModal()">Buka</a></div>`).join(''):''}${!l.length&&!p.length&&!t.length?'<div class="empty">Tidak ada hasil.</div>':''}`)}

function dashboard(v){let m=metrics(),ls=visibleLeads();let counts=Object.fromEntries(stages.map(s=>[s,ls.filter(l=>l.stage===s).length])),max=Math.max(1,...Object.values(counts));let role=session.role;let extra=role==='HOLDING_FINANCE'?`<div class="stats mt">${stat('Pending Verification',allTransactions().filter(t=>t.status==='PENDING_VERIFICATION').length,'warning')}${stat('Due / Overdue',data.projects.flatMap(p=>p.installments.map(i=>installmentStatus(p,i))).filter(s=>['DUE','OVERDUE'].includes(s)).length,'danger')}${stat('Verified Today',allTransactions().filter(t=>t.status==='VERIFIED'&&t.date===TODAY).length,'success')}${stat('Outstanding',money(m.outstanding),'warning')}</div>`:role==='MANAGER_QC'||role==='QC_TEKNIS'?`<div class="stats mt">${stat('Inspection',allInspections().length)}${stat('Open Finding',m.qc)}${stat('Overdue',m.qcOver,'danger')}${stat('Waiting Verify',allFindings().filter(q=>q.status==='WAITING_VERIFICATION').length,'warning')}</div>`:'';v.innerHTML=pageHead(`Dashboard ${roles[role]}`,'Dashboard menyesuaikan role dan tanggung jawab pengguna.')+`<div class="stats">${stat('Project Aktif',m.active)}${stat('Current Contract',money(m.contract))}${stat('Total Paid',money(m.paid),'success')}${stat('Outstanding',money(m.outstanding),'warning')}</div>${extra}<div class="grid2 mt">${card('Sales Pipeline',stages.map(s=>`<div class="pipe-row"><span class="small muted">${stageNames[s]}</span><div class="pipe-bar"><div class="pipe-fill" style="width:${Math.max(7,counts[s]/max*100)}%"></div></div><span class="mono small">${counts[s]}</span></div>`).join(''))}${card('Perlu Perhatian',`<div class="attention"><div class="att-icon">Rp</div><div><div class="att-title">Payment Verification</div><div class="att-text">${m.pending} transaksi menunggu Finance</div></div></div><div class="attention danger" style="margin-top:9px"><div class="att-icon">!</div><div><div class="att-title">QC Overdue</div><div class="att-text">${m.qcOver} finding melewati target</div></div></div><div class="attention" style="margin-top:9px"><div class="att-icon">◷</div><div><div class="att-title">Follow-up Due</div><div class="att-text">${m.follow} lead perlu ditindaklanjuti</div></div></div>`)}</div>`}
function salesDashboard(v){let month=document.querySelector('#salesMonth')?.value||'',ls=visibleLeads().filter(l=>!month||String(l.dateIn||'').startsWith(month)),sales=[...new Set(ls.map(l=>l.sales).filter(Boolean))],sumStage=s=>ls.filter(l=>l.stage===s).reduce((a,l)=>a+leadForecastValue(l),0),daily='';if(session.role==='SALES_EXECUTIVE'){let done=(data.salesDailyReports||[]).some(r=>r.date===TODAY&&belongsToSales(r.sales));daily=`<div class="notice ${done?'success':'warn'} mt"><div class="split"><div><b>Laporan Harian Sales: ${done?'Sudah diisi':'Belum diisi'}</b><div class="small">${done?'Laporan hari ini sudah tersimpan di RMS.':'Sebelum selesai kerja, isi deskripsi kegiatan, hasil, kendala dan rencana tindak lanjut.'}</div></div><a class="btn ${done?'ghost':'primary'} small" href="#/sales-daily-report">${done?'Lihat Laporan':'Isi Laporan Hari Ini'}</a></div></div>`}else if(['HEAD_BU','MANAGER_SALES','SUPER_ADMIN'].includes(session.role)){let submitted=(data.salesDailyReports||[]).filter(r=>r.date===TODAY).length;daily=`<div class="notice info mt"><b>Laporan Harian Sales hari ini:</b> ${submitted} laporan sudah masuk. <a class="link" href="#/sales-daily-report">Buka rekap</a></div>`}v.innerHTML=pageHead('Sales Dashboard','Nilai pipeline memakai Est. ASST CR. Jika Est. ASST CR belum diisi/0, sistem otomatis memakai Est. RAB agar nominal pipeline tetap terbaca.')+`<div class="card mt"><label class="field"><span>BULAN</span><input class="input" type="month" id="salesMonth"></label></div>`+`<div class="stats five">${stat('Warm',money(sumStage('WARM')))}${stat('Hot',money(sumStage('HOT')))}${stat('DP Gambar',money(sumStage('DP_GAMBAR')))}${stat('DP Proyek',money(sumStage('DP_PROYEK')))}${stat('Pembangunan',money(sumStage('PEMBANGUNAN')))}</div>${daily}<div class="grid2 mt">${card('Forecast per Sales',`<div class="table-wrap"><table class="table"><thead><tr><th>Sales</th>${stages.map(s=>`<th>${stageNames[s]}</th>`).join('')}<th>Total</th></tr></thead><tbody>${sales.map(s=>{let a=ls.filter(l=>l.sales===s);return `<tr><td><b>${s}</b></td>${stages.map(st=>`<td class="mono">${money(a.filter(l=>l.stage===st).reduce((x,l)=>x+leadForecastValue(l),0))}</td>`).join('')}<td class="mono"><b>${money(a.reduce((x,l)=>x+leadForecastValue(l),0))}</b></td></tr>`}).join('')}</tbody></table></div><div class="tiny muted mt">Dasar nilai: Est. ASST CR; fallback ke Est. RAB bila Est. ASST CR belum tersedia.</div>`)}${card('Sales Activity Mix',`<div class="metric-list">${['Chat','Telepon','Meeting Offline','Meeting Online'].map(ch=>{let n=data.crm.filter(c=>c.channel===ch&&(session.role!=='SALES_EXECUTIVE'||belongsToSales(c.pic))).length;return `<div class="metric-row"><span>${ch}</span><div class="bar"><i style="width:${Math.min(100,n*25)}%"></i></div><b>${n}</b></div>`}).join('')}</div>`)}</div>`;$('#salesMonth').oninput=()=>salesDashboard(v)}
function leads(v){let ls=visibleLeads();v.innerHTML=pageHead('CRM & Leads','Lead master dengan data komersial lengkap. Gunakan Edit untuk memperbarui data dan Hapus untuk lead yang belum menjadi project.','<button class="btn primary" id="addLead">＋ Lead Baru</button>')+`<div class="card"><div class="card-body"><div class="filterbar"><label class="field grow"><span>CARI</span><input class="input" id="leadSearch" placeholder="Nama client, WA, lokasi..."></label><label class="field"><span>SALES</span><select class="input" id="leadSales"><option value="">Semua</option>${[...new Set(ls.map(l=>l.sales))].map(s=>`<option>${s}</option>`).join('')}</select></label><label class="field"><span>STATUS</span><select class="input" id="leadStage"><option value="">Semua</option>${Object.entries(stageNames).map(([k,n])=>`<option value="${k}">${n}</option>`).join('')}</select></label><label class="field"><span>BULAN</span><input class="input" type="month" id="leadMonth"></label></div></div><div class="table-wrap"><table class="table"><thead><tr><th>Client</th><th>Kebutuhan</th><th>Sales</th><th>DP</th><th>Margin</th><th>Est. Gambar</th><th>Est. RAB</th><th>Stage</th><th>Follow-up</th><th>Aksi</th></tr></thead><tbody id="leadRows"></tbody></table></div></div>`;function draw(){let q=$('#leadSearch').value.toLowerCase(),sls=$('#leadSales').value,st=$('#leadStage').value,month=$('#leadMonth').value,arr=ls.filter(l=>(l.client+l.phone+l.location).toLowerCase().includes(q)&&(!sls||normSales(l.sales)===normSales(sls))&&(!st||l.stage===st)&&(!month||String(l.dateIn||'').startsWith(month)));$('#leadRows').innerHTML=arr.map(l=>`<tr><td><a class="link" href="#/leads/${l.id}">${esc(l.client)}</a><div class="tiny muted">${l.phone} • ${l.location}</div></td><td>${esc(l.need)}</td><td>${esc(l.sales)}</td><td>${pct(l.dp)}</td><td>${pct(l.margin)}</td><td class="mono">${money(l.estGambar)}</td><td class="mono">${money(l.estRab)}</td><td>${badge(l.stage)}</td><td>${date(l.nextFollowUp)}${l.nextFollowUp&&l.nextFollowUp<=TODAY?'<div class="tiny danger"><b>DUE/OVERDUE</b></div>':''}</td><td><div class="action-row">${canEditLead(l)?`<button class="btn ghost small editLeadRow" data-id="${l.id}">Edit</button>`:''}${canDeleteLead(l)?`<button class="btn danger small delLeadRow" data-id="${l.id}">Hapus</button>`:''}${!canEditLead(l)&&!canDeleteLead(l)?'-':''}</div></td></tr>`).join('')||'<tr><td colspan="10" class="empty">Tidak ada data.</td></tr>';$$('.editLeadRow').forEach(btn=>btn.onclick=()=>leadModal(leadById(btn.dataset.id)));$$('.delLeadRow').forEach(btn=>btn.onclick=()=>deleteLead(leadById(btn.dataset.id),()=>{ls=visibleLeads();draw()}))}draw();['leadSearch','leadSales','leadStage','leadMonth'].forEach(id=>$('#'+id).oninput=draw);$('#addLead').onclick=()=>leadModal()}
function leadModal(edit){let l=edit||{};openModal(edit?'Edit Lead':'Tambah Lead Baru',`<form id="leadForm"><div class="form-grid"><label class="field"><span>TGL MASUK</span><input type="date" class="input" name="dateIn" value="${l.dateIn||TODAY}" required></label><label class="field"><span>NAMA CLIENT</span><input class="input" name="client" value="${esc(l.client||'')}" required></label><label class="field"><span>NO WA</span><input class="input" name="phone" value="${esc(l.phone||'')}" required></label><label class="field"><span>SUMBER</span><select class="input" name="source">${data.settings.leadSources.map(x=>`<option ${l.source===x?'selected':''}>${x}</option>`).join('')}</select></label><label class="field"><span>LOKASI</span><input class="input" name="location" value="${esc(l.location||'')}" required></label><label class="field"><span>KEBUTUHAN</span><input class="input" name="need" value="${esc(l.need||'Rumah')}" required></label><label class="field"><span>% DP</span><input type="number" min="0" max="100" class="input" name="dp" value="${l.dp??20}" required></label><label class="field"><span>% MARGIN</span><input type="number" min="0" max="100" class="input" name="margin" value="${l.margin??8}" required></label><label class="field"><span>EST GAMBAR</span><input type="number" class="input" name="estGambar" value="${l.estGambar||0}"></label><label class="field"><span>EST RAB</span><input type="number" class="input" name="estRab" value="${l.estRab||0}"></label><label class="field"><span>EST ASST CR</span><input type="number" class="input" name="estAsstCr" value="${l.estAsstCr||0}"></label>${(()=>{let opts=[...new Set([...salesDirectoryNames(),l.sales].filter(Boolean))];if(session?.role==='SALES_EXECUTIVE')opts=[session.scopeName||session.name];return `<label class="field"><span>SALES PIC</span><select class="input" name="sales" required>${opts.map(x=>`<option ${normSales(l.sales)===normSales(x)?'selected':''}>${esc(x)}</option>`).join('')}</select><small class="tiny muted">Mengikuti akun Sales aktif di User Management.</small></label>`})()}<label class="field"><span>NEXT FOLLOW UP</span><input type="date" class="input" name="nextFollowUp" value="${l.nextFollowUp||''}"></label><label class="field" style="grid-column:1/-1"><span>CATATAN</span><textarea class="input" name="notes" rows="3">${esc(l.notes||'')}</textarea></label></div><button class="btn primary" style="width:100%">${edit?'Simpan Perubahan':'Buat Lead'}</button></form>`);setTimeout(()=>{$('#leadForm').onsubmit=e=>{e.preventDefault();let x=Object.fromEntries(new FormData(e.target));['dp','margin','estGambar','estRab','estAsstCr'].forEach(k=>x[k]=Number(x[k]||0));x.sales=salesDisplay((salesDirectory||[]).find(u=>normSales(salesDisplay(u))===normSales(x.sales)))||x.sales;if(edit){Object.assign(edit,x);recomputeLeadStage(edit);addAudit(currentActor(),'LEAD',edit.id,'UPDATE','Data lead diperbarui dan pipeline dievaluasi ulang')}else{let n={id:uid('LD'),...x,stage:'WARM',lastActivity:TODAY,milestones:['Kebutuhan teridentifikasi']};data.leads.unshift(n);recomputeLeadStage(n);addAudit(currentActor(),'LEAD',n.id,'CREATE','Lead baru dibuat; pipeline dievaluasi otomatis')}save();closeModal();route()}},0)}
function leadDetail(v,r){let l=leadById(r.id);if(!l)return v.innerHTML=pageHead('Lead tidak ditemukan','');let p=projectForLead(l.id),canPay=['MANAGER_SALES','ADMIN_GENERAL','SALES_EXECUTIVE','ADMIN_CRM','HOLDING_FINANCE','SUPER_ADMIN','HEAD_BU'].includes(session.role),canSide=['HEAD_BU','MANAGER_SALES','SUPER_ADMIN'].includes(session.role),next=nextStageInfo(l);let paymentButtons='';if(canPay&&l.stage==='HOT')paymentButtons=`<button class="btn primary payFromLead" data-type="DP_GAMBAR">Upload DP Gambar</button> <button class="btn ghost payFromLead" data-type="DP_PROYEK">Upload DP Proyek (skip gambar)</button>`;if(canPay&&l.stage==='DP_GAMBAR')paymentButtons=`<button class="btn primary payFromLead" data-type="DP_PROYEK">Upload DP Proyek</button>`;v.innerHTML=pageHead(l.client,`${l.id} • ${l.phone} • ${l.location}`,`${canEditLead(l)?'<button class="btn ghost" id="editLead">Edit Lead</button>':''}${canDeleteLead(l)?' <button class="btn danger" id="deleteLead">Hapus Lead</button>':''}`)+stagePath(l)+`<div class="notice info mt"><b>Next: ${next.next}</b><br>${esc(next.text)}</div><div class="grid2 mt">${card('Data Client',`<div class="grid2eq">${info('Tanggal Masuk',date(l.dateIn))}${info('Sumber',l.source)}${info('Lokasi',l.location)}${info('Kebutuhan',l.need)}${info('Sales PIC',l.sales)}${info('Current Stage',badge(l.stage))}</div>`)}${card('Commercial Estimation',`<div class="grid2eq">${info('% DP',pct(l.dp))}${info('% Margin',pct(l.margin))}${info('Est. Gambar',money(l.estGambar))}${info('Est. RAB',money(l.estRab))}${info('Est. ASST CR',money(l.estAsstCr))}${info('Next Follow-up',date(l.nextFollowUp))}</div>`)}</div><div class="grid2 mt">${card('Milestone',`<div class="stack">${l.milestones.map(m=>`<div class="check"><span class="checkmark">✓</span>${m}</div>`).join('')}<button class="btn ghost small" id="addMilestone">＋ Tambah Milestone</button></div>`)}${(()=>{let q=hotQualification(l),items=[['Kebutuhan tersedia',q.need],['Lokasi tersedia',q.location],['Est. RAB tersedia',q.estRab],['Sales PIC tersedia',q.sales],['Next follow-up tersedia',q.nextAction],['Milestone Survey / Proposal / Meeting',q.milestone]],missing=items.filter(x=>!x[1]).map(x=>x[0]);return card('Qualification & Pipeline Control',`<div class="notice info">${esc(l.notes||'-')}</div><div style="margin-top:12px">${items.map(([x,ok])=>`<div class="check"><span class="checkmark">${ok?'✓':'○'}</span>${x}</div>`).join('')}</div>${l.stage==='WARM'?`<div class="notice warn" style="margin-top:12px"><b>Agar pindah ke HOT:</b> ${missing.length?missing.join(' • '):'Simpan milestone; sistem mengevaluasi otomatis.'}</div>`:''}${paymentButtons?`<div class="mt">${paymentButtons}</div>`:''}${p?`<div class="mt"><a class="btn ghost" href="#/projects/${p.id}">Buka Project Dossier ${p.id}</a></div>`:''}${canSide?`<div class="mt pipeline-side-actions">${l.stage==='HOLD_BATAL'?'<button class="btn primary" id="resumeLead">Aktifkan Kembali</button>':'<button class="btn ghost" id="holdLead">Hold / Batal</button>'}</div>`:''}`)})()}</div><div class="mt">${chatBox(l.chat,'leadChatForm','Chat Internal Lead')}</div>`;if($('#editLead'))$('#editLead').onclick=()=>leadModal(l);if($('#deleteLead'))$('#deleteLead').onclick=()=>deleteLead(l);$('#addMilestone').onclick=()=>openModal('Tambah Milestone',`<form id="mileForm"><select class="input" name="m"><option>Survey selesai</option><option>Proposal/RAB dikirim</option><option>Meeting penawaran selesai</option></select><button class="btn primary" style="width:100%;margin-top:12px">Simpan</button></form>`,()=>{let f=$('#mileForm');if(f)f.onsubmit=async e=>{e.preventDefault();let m=new FormData(e.target).get('m');if(!l.milestones.includes(m))l.milestones.push(m);l.lastActivity=TODAY;addLeadChat(l,currentActor(),`Milestone: ${m}`);recomputeLeadStage(l,true);save();closeModal();leadDetail(v,r)}});$$('.payFromLead').forEach(btn=>btn.onclick=()=>{let pr=ensureProjectForLead(l);paymentModal(pr,btn.dataset.type,l.id)});if($('#holdLead'))$('#holdLead').onclick=()=>openModal('Hold / Batal Lead',`<form id="sideForm"><label class="field"><span>STATUS</span><select class="input" name="side"><option value="HOLD">HOLD</option><option value="BATAL">BATAL</option></select></label><label class="field"><span>ALASAN (WAJIB)</span><textarea class="input" name="reason" required></textarea></label><button class="btn danger" style="width:100%">Simpan Status</button></form>`,()=>{if($('#sideForm'))$('#sideForm').onsubmit=e=>{e.preventDefault();let fd=new FormData(e.target);l.previousStage=l.stage;l.pipelineSide=fd.get('side');l.sideReason=fd.get('reason');l.stage='HOLD_BATAL';addAudit(currentActor(),'PIPELINE',l.id,'HOLD_BATAL',`${l.pipelineSide}: ${l.sideReason}`);addLeadChat(l,'System',`Pipeline masuk ${l.pipelineSide}: ${l.sideReason}`,true);save();closeModal();leadDetail(v,r)}});if($('#resumeLead'))$('#resumeLead').onclick=()=>{l.pipelineSide='';l.sideReason='';l.stage=l.previousStage||'WARM';recomputeLeadStage(l,true);save();leadDetail(v,r)};let cf=$('#leadChatForm');if(cf)cf.onsubmit=async e=>{e.preventDefault();let fd=new FormData(e.target),file=e.target.attachment.files[0],up=file?await uploadFile(file,'LEAD_CHAT',l.id):null;addLeadChat(l,currentActor(),fd.get('message'),false,up?.name||'',up?.id||'');addAudit(currentActor(),'LEAD_CHAT',l.id,'MESSAGE','Pesan internal lead');save();leadDetail(v,r)}}
function pipeline(v){let ls=visibleLeads();v.innerHTML=pageHead('Sales Pipeline','Tabel ini mengikuti kolom utama sheet Pipeline pada Dashboard Rumsy 2026. Kanban tetap terpisah dan read-only.')+`<div class="summary-strip">${Object.entries(stageNames).map(([k,n])=>`<div class="summary-chip"><small>${n}</small><b>${ls.filter(l=>l.stage===k).length} lead</b><div class="tiny muted">${money(ls.filter(l=>l.stage===k).reduce((s,l)=>s+leadForecastValue(l),0))}</div></div>`).join('')}</div><div class="card mt"><div class="card-body"><div class="filterbar"><label class="field grow"><span>SEARCH</span><input class="input" id="pSearch" placeholder="Client / WA / lokasi / kebutuhan"></label><label class="field"><span>SALES</span><select class="input" id="pSales"><option value="">Semua</option>${[...new Set(ls.map(l=>l.sales))].map(x=>`<option>${x}</option>`).join('')}</select></label><label class="field"><span>SUMBER</span><select class="input" id="pSource"><option value="">Semua</option>${[...new Set(ls.map(l=>l.source))].map(x=>`<option>${x}</option>`).join('')}</select></label><label class="field"><span>STATUS</span><select class="input" id="pStage"><option value="">Semua</option>${Object.entries(stageNames).map(([k,n])=>`<option value="${k}">${n}</option>`).join('')}</select></label><label class="field"><span>BULAN</span><input class="input" type="month" id="pMonth"></label></div></div><div class="scroll-wide"><table class="table pipeline-table"><thead><tr><th class="sticky-left">TGL MASUK</th><th>NAMA CLIENT</th><th>NO WA</th><th>SUMBER</th><th>LOKASI</th><th>KEBUTUHAN</th><th>% DP</th><th>% MARGIN</th><th>EST GAMBAR</th><th>EST RAB</th><th>EST ASST CR</th><th>CATATAN</th><th>SALES</th><th>STATUS</th></tr></thead><tbody id="pRows"></tbody></table></div></div>`;function draw(){let q=$('#pSearch').value.toLowerCase(),sales=$('#pSales').value,src=$('#pSource').value,st=$('#pStage').value,m=$('#pMonth').value,a=ls.filter(l=>(l.client+l.phone+l.location+l.need).toLowerCase().includes(q)&&(!sales||l.sales===sales)&&(!src||l.source===src)&&(!st||l.stage===st)&&(!m||String(l.dateIn||'').startsWith(m)));$('#pRows').innerHTML=a.map(l=>`<tr><td class="sticky-left nowrap">${date(l.dateIn)}</td><td><a class="link" href="#/leads/${l.id}">${l.client}</a></td><td class="nowrap">${l.phone}</td><td>${l.source}</td><td>${l.location}</td><td>${l.need}</td><td class="center"><b>${pct(l.dp)}</b></td><td class="center"><b>${pct(l.margin)}</b></td><td class="mono right">${money(l.estGambar)}</td><td class="mono right">${money(l.estRab)}</td><td class="mono right"><b>${money(l.estAsstCr)}</b></td><td>${esc(l.notes)}</td><td>${l.sales}</td><td>${badge(l.stage)}</td></tr>`).join('')||'<tr><td colspan="14" class="empty">Tidak ada data.</td></tr>'}draw();['pSearch','pSales','pSource','pStage','pMonth'].forEach(id=>$('#'+id).oninput=draw)}
function kanban(v){normalizeLeadStages();let ls=visibleLeads();v.innerHTML=pageHead('Sales Kanban — Otomatis','Kanban hanya visualisasi. Tidak ada drag & drop. Stage berubah dari milestone, payment VERIFIED, handover, project start dan completion gate.')+`<div class="notice info"><b>READ ONLY:</b> user melakukan pekerjaan; sistem menentukan posisi client. Buka kartu untuk melihat syarat stage berikutnya.</div><div class="kanban-wrap mt"><div class="kanban" style="grid-template-columns:repeat(7,210px);min-width:1540px">${[...stages,'HOLD_BATAL'].map(s=>`<div class="kcol ${s==='HOLD_BATAL'?'side':''}"><div class="khead"><span>${stageNames[s]}</span><span>${ls.filter(l=>l.stage===s).length}</span></div>${ls.filter(l=>l.stage===s).map(l=>{let n=nextStageInfo(l);return `<div class="kcard"><b>${esc(l.client)}</b><div class="tiny muted">${esc(l.location)} • ${esc(l.sales)}</div><div class="kv"><div>Est. RAB<b>${money(l.estRab)}</b></div><div>Est. ASST CR<b>${money(l.estAsstCr)}</b></div><div>DP<b>${pct(l.dp)}</b></div><div>Margin<b>${pct(l.margin)}</b></div></div><div class="next"><b>Next: ${n.next}</b><br>${esc(n.text)}</div><a class="btn ghost small" style="margin-top:9px" href="#/leads/${l.id}">Buka Lead</a></div>`}).join('')}</div>`).join('')}</div></div>`}
function forecast(v){let ls=rmsSalesDashboardMonthFilter(visibleLeads()),sales=[...new Set(ls.map(l=>l.sales))];v.innerHTML=pageHead('Forecast','Matriks nilai per Sales dan stage berdasarkan Est. ASST CR; layout mengacu pada konsep Forecast Excel.')+card('Forecast Value',`<div class="table-wrap"><table class="table" style="min-width:1000px"><thead><tr><th>Sales</th>${[...stages,'HOLD_BATAL'].map(s=>`<th>${stageNames[s]}</th>`).join('')}<th>TOTAL</th></tr></thead><tbody>${sales.map(s=>{let a=ls.filter(l=>l.sales===s);return `<tr><td><b>${s}</b></td>${[...stages,'HOLD_BATAL'].map(st=>`<td class="mono right">${money(a.filter(l=>l.stage===st).reduce((x,l)=>x+leadForecastValue(l),0))}</td>`).join('')}<td class="mono right"><b>${money(a.reduce((x,l)=>x+leadForecastValue(l),0))}</b></td></tr>`}).join('')}<tr><td><b>TOTAL</b></td>${[...stages,'HOLD_BATAL'].map(st=>`<td class="mono right"><b>${money(ls.filter(l=>l.stage===st).reduce((x,l)=>x+leadForecastValue(l),0))}</b></td>`).join('')}<td class="mono right"><b>${money(ls.reduce((x,l)=>x+leadForecastValue(l),0))}</b></td></tr></tbody></table></div>`)+`<div class="grid2 mt">${card('Lead by Source',`<div class="metric-list">${[...new Set(ls.map(l=>l.source))].map(s=>{let n=ls.filter(l=>l.source===s).length;return `<div class="metric-row"><span>${s}</span><div class="bar"><i style="width:${n/ls.length*100}%"></i></div><b>${n}</b></div>`}).join('')}</div>`)}${card('Quick Metrics',`<div class="grid2eq">${info('Total Pipeline',money(ls.reduce((s,l)=>s+leadForecastValue(l),0)))}${info('Avg Est. RAB',money(ls.reduce((s,l)=>s+l.estRab,0)/Math.max(1,ls.length)))}${info('Closing/Selesai',ls.filter(l=>l.stage==='SELESAI').length)}${info('Hold/Batal',ls.filter(l=>l.stage==='HOLD_BATAL').length)}</div>`)}</div>`}
function activity(v){let rows=session.role==='SALES_EXECUTIVE'?data.crm.filter(c=>belongsToSales(c.pic)):data.crm;v.innerHTML=pageHead('Activity / Backlog','Struktur mengikuti sheet Backlog: Tanggal, Client, Kategori, Jenis Layanan, Perihal, PIC, Catatan.','<button class="btn primary" id="addAct">＋ Activity</button>')+card('CRM Backlog',`<div class="table-wrap"><table class="table"><thead><tr><th>Tanggal</th><th>Nama Client</th><th>Kategori</th><th>Jenis Layanan</th><th>Perihal</th><th>PIC</th><th>Catatan</th><th>Next Follow-up</th></tr></thead><tbody>${rows.map(x=>`<tr><td>${date(x.date)}</td><td><b>${x.client}</b></td><td>${x.category}</td><td>${x.channel}</td><td>${x.subject}</td><td>${x.pic}</td><td>${x.notes||'-'}</td><td>${date(x.next)}${x.next&&x.next<=TODAY?'<div class="tiny danger"><b>DUE</b></div>':''}</td></tr>`).join('')}</tbody></table></div>`);$('#addAct').onclick=()=>openModal('Tambah CRM Activity',`<form id="actForm"><div class="form-grid"><label class="field"><span>TANGGAL</span><input type="date" class="input" name="date" value="${TODAY}"></label><label class="field"><span>NAMA CLIENT / LEAD</span><select class="input" name="leadId" id="activityLeadSelect" required><option value="">Pilih Lead</option></select><input type="hidden" name="client" id="activityClientName"></label>
<label class="field"><span>NOMOR TELEPON</span><input class="input" name="phone" id="activityPhone" readonly></label>
<label class="field"><span>EMAIL</span><input class="input" name="email" id="activityEmail" readonly></label><label class="field"><span>KATEGORI</span><select class="input" name="category"><option>Baru</option><option>Lama</option></select></label><label class="field"><span>JENIS LAYANAN</span><select class="input" name="channel"><option>Chat</option><option>Telepon</option><option>Meeting Offline</option><option>Meeting Online</option></select></label><label class="field"><span>PERIHAL</span><select class="input" name="subject"><option>Belum teridentifikasi</option><option>Tanya produk</option><option>Tanya progress pembangunan</option><option>Payment DP Gambar</option><option>Payment DP Proyek</option><option>Komplain</option></select></label>${(()=>{let opts=session.role==='SALES_EXECUTIVE'?[session.scopeName||session.name]:[...new Set([...salesDirectoryNames(),'CS'].filter(Boolean))];return `<label class="field"><span>PIC</span><select class="input" name="pic">${opts.map(x=>`<option>${esc(x)}</option>`).join('')}</select></label>`})()}<label class="field"><span>NEXT FOLLOW UP</span><input type="date" class="input" name="next"></label><label class="field" style="grid-column:1/-1"><span>CATATAN</span><textarea class="input" name="notes"></textarea></label></div><button class="btn primary" style="width:100%">Simpan Activity</button></form>`,()=>{
const leadSelect=$('#activityLeadSelect');
const leadsForActivity=visibleLeads();
leadSelect.innerHTML='<option value="">Pilih Lead</option>'+leadsForActivity.map(l=>`<option value="${esc(l.id)}">${esc(l.client||'')} — ${esc(l.phone||'')}</option>`).join('');
leadSelect.onchange=()=>{
 const lead=leadsForActivity.find(l=>l.id===leadSelect.value);
 $('#activityClientName').value=lead?.client||'';
 $('#activityPhone').value=lead?.phone||'';
 $('#activityEmail').value=lead?.email||'';
};
$('#actForm').onsubmit=e=>{e.preventDefault();let x=Object.fromEntries(new FormData(e.target));
let lead=(data.leads||[]).find(l=>l.id===x.leadId);
if(lead){
 x.client=lead.client||lead.name||lead.clientName||'';
 x.phone=lead.phone||lead.mobile||'';
 x.email=lead.email||'';
}
data.crm.unshift({id:uid('CRM'),...x});save();closeModal();activity(v)}})}
function salesReportMetrics(reportDate,sales){let leads=data.leads.filter(l=>l.dateIn===reportDate&&normSales(l.sales)===normSales(sales));let acts=data.crm.filter(a=>a.date===reportDate&&normSales(a.pic)===normSales(sales));let count=ch=>acts.filter(a=>a.channel===ch).length;let owned=data.leads.filter(l=>normSales(l.sales)===normSales(sales)&&l.stage!=='HOLD_BATAL');return {newLeads:leads.length,chat:count('Chat'),calls:count('Telepon'),meetingOffline:count('Meeting Offline'),meetingOnline:count('Meeting Online'),activities:acts.length,followUpDue:owned.filter(l=>l.nextFollowUp===reportDate).length,pipelineValue:owned.reduce((n,l)=>n+leadForecastValue(l),0)}}
function visibleSalesDailyReports(){return session?.role==='SALES_EXECUTIVE'?data.salesDailyReports.filter(r=>belongsToSales(r.sales)):data.salesDailyReports}
function salesDailyReport(v){data.salesDailyReports??=[];let rows=[...visibleSalesDailyReports()].sort((a,b)=>(String(b.date)+String(b.createdAt||'')).localeCompare(String(a.date)+String(a.createdAt||'')));let todayRows=rows.filter(r=>r.date===TODAY);v.innerHTML=pageHead('Laporan Harian Sales','Laporan harian Sales terhubung dengan data Lead dan Activity. Sales menuliskan deskripsi kegiatan yang dilakukan, hasil/capaian, kendala, dan rencana tindak lanjut; angka aktivitas dihitung otomatis dari RMS.',canManageSalesDaily()?'<button class="btn primary" id="newSalesDaily">＋ Buat Laporan Hari Ini</button>':'')+`<div class="stats">${stat('Laporan Hari Ini',todayRows.length)}${stat('Lead Baru Hari Ini',todayRows.reduce((n,r)=>n+(r.metrics?.newLeads||0),0))}${stat('Aktivitas Hari Ini',todayRows.reduce((n,r)=>n+(r.metrics?.activities||0),0))}${stat('Meeting Hari Ini',todayRows.reduce((n,r)=>n+(r.metrics?.meetingOffline||0)+(r.metrics?.meetingOnline||0),0))}</div><div class="card mt"><div class="card-body"><div class="filterbar"><label class="field"><span>TANGGAL</span><input type="date" class="input" id="dailyDate"></label><label class="field grow"><span>CARI</span><input class="input" id="dailySearch" placeholder="Nama Sales, kegiatan, hasil, kendala, rencana..."></label></div></div><div class="table-wrap"><table class="table"><thead><tr><th>Tanggal</th><th>Sales</th><th>Lead Baru</th><th>Chat</th><th>Telepon</th><th>Meeting</th><th>Total Aktivitas</th><th>Kegiatan & Hasil</th><th>Aksi</th></tr></thead><tbody id="dailyRows"></tbody></table></div></div>`;
function draw(){let d=$('#dailyDate').value,q=$('#dailySearch').value.toLowerCase(),arr=rows.filter(r=>(!d||r.date===d)&&(!q||[r.sales,r.activityDescription,r.result,r.obstacle,r.nextPlan].some(x=>String(x||'').toLowerCase().includes(q))));$('#dailyRows').innerHTML=arr.map(r=>{let m=r.metrics||salesReportMetrics(r.date,r.sales),canOwn=canManageSalesDaily(r);return `<tr><td>${date(r.date)}</td><td><b>${esc(r.sales)}</b></td><td>${m.newLeads||0}</td><td>${m.chat||0}</td><td>${m.calls||0}</td><td>${(m.meetingOffline||0)+(m.meetingOnline||0)}</td><td><b>${m.activities||0}</b></td><td><div><b>Kegiatan:</b> ${esc(r.activityDescription||'-')}</div><div class="tiny" style="margin-top:6px"><b>Hasil:</b> ${esc(r.result||'-')}</div>${r.obstacle?`<div class="tiny danger"><b>Kendala:</b> ${esc(r.obstacle)}</div>`:''}${r.nextPlan?`<div class="tiny muted"><b>Rencana:</b> ${esc(r.nextPlan)}</div>`:''}</td><td><div class="action-row">${canOwn?`<button class="btn ghost small editDaily" data-id="${r.id}">Edit</button><button class="btn danger small delDaily" data-id="${r.id}">Hapus</button>`:'-'}</div></td></tr>`}).join('')||'<tr><td colspan="9" class="empty">Belum ada laporan harian.</td></tr>';$$('.editDaily').forEach(btn=>btn.onclick=()=>dailyModal(data.salesDailyReports.find(x=>x.id===btn.dataset.id)));$$('.delDaily').forEach(btn=>btn.onclick=async()=>{let r=data.salesDailyReports.find(x=>x.id===btn.dataset.id);if(!r||!confirm(`Hapus laporan ${r.sales} tanggal ${date(r.date)}?`))return;data.salesDailyReports=data.salesDailyReports.filter(x=>x.id!==r.id);addAudit(currentActor(),'SALES_DAILY_REPORT',r.id,'DELETE',`${r.sales} • ${r.date}`);await save();salesDailyReport(v)})}
function dailyModal(edit=null){let r=edit||{},salesOpts=session.role==='SALES_EXECUTIVE'?[session.scopeName||session.name]:[...new Set([...salesDirectoryNames(),...data.leads.map(l=>l.sales)].filter(Boolean))];openModal(edit?'Edit Laporan Harian Sales':'Buat Laporan Harian Sales',`<form id="dailyForm"><div class="form-grid"><label class="field"><span>TANGGAL</span><input type="date" class="input" name="date" value="${r.date||TODAY}" required></label><label class="field"><span>SALES</span><select class="input" name="sales">${salesOpts.map(x=>`<option ${normSales(r.sales||salesOpts[0])===normSales(x)?'selected':''}>${esc(x)}</option>`).join('')}</select></label></div><div class="notice info" id="dailyAuto" style="margin:12px 0">Data aktivitas akan dihitung otomatis dari Lead dan Activity RMS.</div><label class="field"><span>DESKRIPSI KEGIATAN / AKTIVITAS YANG DILAKUKAN</span><textarea class="input" name="activityDescription" rows="4" required placeholder="Contoh: Follow-up via WhatsApp ke 5 client, melakukan meeting penawaran dengan Bu A, dan koordinasi jadwal survey Pak B.">${esc(r.activityDescription||'')}</textarea></label><label class="field"><span>HASIL / CAPAIAN HARI INI</span><textarea class="input" name="result" rows="3" required placeholder="Contoh: 2 client lanjut estimasi RAB, 1 client menjadwalkan survey, 1 client meminta revisi penawaran.">${esc(r.result||'')}</textarea></label><label class="field"><span>KENDALA</span><textarea class="input" name="obstacle" rows="3" placeholder="Isi bila ada kendala.">${esc(r.obstacle||'')}</textarea></label><label class="field"><span>RENCANA TINDAK LANJUT / BESOK</span><textarea class="input" name="nextPlan" rows="3" required placeholder="Contoh: Follow-up Pak A, kirim proposal Bu B, jadwalkan survey.">${esc(r.nextPlan||'')}</textarea></label><button class="btn primary" style="width:100%">Simpan Laporan Harian</button></form>`,()=>{let f=$('#dailyForm'),renderAuto=()=>{let m=salesReportMetrics(f.date.value,f.sales.value);$('#dailyAuto').innerHTML=`<b>Rekap Otomatis RMS:</b> Lead Baru ${m.newLeads} • Chat ${m.chat} • Telepon ${m.calls} • Meeting Offline ${m.meetingOffline} • Meeting Online ${m.meetingOnline} • Total Aktivitas ${m.activities} • Follow-up jatuh tempo ${m.followUpDue} • Pipeline ${money(m.pipelineValue)}`};renderAuto();f.date.onchange=renderAuto;f.sales.onchange=renderAuto;f.onsubmit=async e=>{e.preventDefault();let x=Object.fromEntries(new FormData(e.target)),duplicate=data.salesDailyReports.find(y=>y.id!==r.id&&y.date===x.date&&normSales(y.sales)===normSales(x.sales));if(duplicate){alert('Laporan harian untuk Sales dan tanggal tersebut sudah ada. Gunakan tombol Edit pada laporan yang sudah tersimpan.');return}let metrics=salesReportMetrics(x.date,x.sales);if(edit){Object.assign(r,x,{metrics,updatedAt:nowLabel(),updatedBy:currentActor()});addAudit(currentActor(),'SALES_DAILY_REPORT',r.id,'UPDATE',`${x.sales} • ${x.date}`)}else{let n={id:uid('SDR'),...x,metrics,createdAt:nowLabel(),createdBy:currentActor()};data.salesDailyReports.unshift(n);addAudit(currentActor(),'SALES_DAILY_REPORT',n.id,'CREATE',`${x.sales} • ${x.date}`)}await save();closeModal();salesDailyReport(v)}})}
if($('#newSalesDaily'))$('#newSalesDaily').onclick=()=>dailyModal();$('#dailyDate').onchange=draw;$('#dailySearch').oninput=draw;draw()}

function clients(v){let cs=data.clients;v.innerHTML=pageHead('Client Database','Client terpisah dari Project sehingga satu client dapat memiliki banyak proyek.')+`<div class="project-grid">${cs.map(c=>{let ps=data.projects.filter(p=>p.clientId===c.id);return `<a class="client-card" href="#/clients/${c.id}" style="text-decoration:none;color:inherit"><h3>${c.name}</h3><div class="meta">${c.phone} • ${c.address}</div><div class="project-count">${ps.length} Project • ${money(ps.reduce((s,p)=>s+currentContract(p),0))}</div></a>`}).join('')}</div>`}
