function canManageProject(){return ['HEAD_BU','MANAGER_OPERASIONAL','ADMIN_GENERAL','SUPER_ADMIN'].includes(session.role)}
function projectFormModal(edit=null){let p=edit||{},isEdit=!!edit;let salesSel=p.salesUserId||userByName(p.sales)?.id||'',opsSel=p.opsUserId||userByName(p.ops)?.id||'',qcSel=p.qcUserId||userByName(p.qc)?.id||'';openModal(isEdit?'Edit Project':'Tambah Project',`<form id="projectForm"><div class="form-grid"><label class="field"><span>NAMA PROJECT</span><input class="input" name="name" value="${esc(p.name||'')}" required></label><label class="field"><span>NAMA KLIEN</span><input class="input" name="client" value="${esc(p.client||'')}" required></label><label class="field"><span>LOKASI</span><input class="input" name="location" value="${esc(p.location||'')}" required></label><label class="field"><span>SALES PIC</span><select class="input" name="salesUserId">${userOptions(salesSel,['SALES_EXECUTIVE'])}</select></label><label class="field"><span>PIC OPERASIONAL</span><select class="input" name="opsUserId">${userOptions(opsSel,['MANAGER_OPERASIONAL','HEAD_BU','ADMIN_GENERAL'])}</select></label><label class="field"><span>PIC QC</span><select class="input" name="qcUserId">${userOptions(qcSel,['MANAGER_QC','QC_TEKNIS'])}</select></label>${isEdit?'':`<label class="field"><span>NILAI KONTRAK AWAL</span><input type="number" class="input" name="originalContract" value="0"></label><label class="field"><span>TANGGAL MULAI</span><input type="date" class="input" name="startDate"></label><label class="field"><span>TARGET SELESAI</span><input type="date" class="input" name="targetFinish"></label>`}</div><div class="notice info">PIC dipilih dari akun aktif RMS sehingga nama dan email tidak perlu diketik manual.</div><button class="btn primary" style="width:100%;margin-top:12px">${isEdit?'Simpan Perubahan':'Buat Project'}</button></form>`,()=>{$('#projectForm').onsubmit=async e=>{e.preventDefault();let x=Object.fromEntries(new FormData(e.target)),salesU=userById(x.salesUserId),opsU=userById(x.opsUserId),qcU=userById(x.qcUserId);if(isEdit){Object.assign(p,{name:x.name,client:x.client,location:x.location,sales:salesU?.scopeName||salesU?.name||'',salesUserId:x.salesUserId||'',ops:opsU?.name||'',opsUserId:x.opsUserId||'',qc:qcU?.name||'',qcUserId:x.qcUserId||''});let c=data.clients.find(c=>c.id===p.clientId);if(c){c.name=x.client;c.address=x.location}addProjectActivity(p,currentActor(),'Data project dan PIC diperbarui.');addAudit(currentActor(),'PROJECT',p.id,'UPDATE','Informasi project diperbarui')}else{let c=data.clients.find(c=>c.name.trim().toLowerCase()===x.client.trim().toLowerCase());if(!c){c={id:uid('CL'),name:x.client,phone:'',email:'',address:x.location,notes:''};data.clients.unshift(c)}let n={id:`RMS-PRJ-${new Date().getFullYear()}-${Date.now().toString(36).toUpperCase()}`,clientId:c.id,leadId:null,name:x.name,client:x.client,location:x.location,sales:salesU?.scopeName||salesU?.name||'',salesUserId:x.salesUserId||'',ops:opsU?.name||'',opsUserId:x.opsUserId||'',qc:qcU?.name||'',qcUserId:x.qcUserId||'',status:'PREPARATION',progress:0,originalContract:Number(x.originalContract||0),startDate:x.startDate||'',targetFinish:x.targetFinish||'',actualFinish:'',contract:{number:'',date:'',status:'DRAFT',dp:0,margin:0,tenor:0},handover:{status:'DRAFT',submittedAt:'',reviewedAt:'',note:''},started:false,completionApproved:false,transactions:[],installments:[],addendums:[],documents:[],inspections:[],qcFindings:[],progressDaily:[],progressWeekly:[],clientPortal:{enabled:false,token:'',createdAt:''},activity:[],chat:[]};data.projects.unshift(n);addProjectActivity(n,currentActor(),'Project dibuat manual.');addProjectChat(n,'System','Project dossier dibuat.',true);addAudit(currentActor(),'PROJECT',n.id,'CREATE','Project baru dibuat')}await save();closeModal();route()}})}
async function deleteProject(p){if(!['HEAD_BU','SUPER_ADMIN'].includes(session.role))return alert('Hanya Head BU / Super Admin yang dapat menghapus project.');if((p.transactions||[]).some(t=>t.status==='VERIFIED'))return alert('Project tidak dapat dihapus karena sudah memiliki transaksi VERIFIED. Perbaiki data melalui Edit Project atau arsipkan project.');if(!confirm(`Hapus Project ${p.name}? Tindakan ini untuk project salah input dan tidak dapat dibatalkan.`))return;let ids=[...(p.documents||[]).map(x=>x.fileId),...(p.transactions||[]).map(x=>x.proofFileId),...(p.progressDaily||[]).map(x=>x.fileId),...(p.progressWeekly||[]).map(x=>x.fileId),...(p.chat||[]).map(x=>x.fileId)].filter(Boolean);data.projects=data.projects.filter(x=>x.id!==p.id);addAudit(currentActor(),'PROJECT',p.id,'DELETE','Project salah input dihapus');await save();await Promise.allSettled(ids.map(removeFile));location.hash='#/projects';route()}
function projectDashboard(v){
let ps=visibleProjects(),total=ps.length;
let active=ps.filter(p=>p.status!=='COMPLETED'),completed=ps.filter(p=>p.status==='COMPLETED');
let hold=ps.filter(p=>['HOLD','HOLD_BATAL'].includes(p.status));
let late=ps.filter(p=>p.status!=='COMPLETED'&&p.targetFinish&&String(p.targetFinish)<TODAY);
let contract=ps.reduce((s,p)=>s+currentContract(p),0);
let paid=ps.reduce((s,p)=>s+verifiedPaid(p),0);
let outstanding=contract-paid;
let findings=ps.flatMap(p=>p.qcFindings||[]);
let tasks=(data.tasks||[]).filter(t=>ps.some(p=>String(p.id)===String(t.projectId)));
let avgProgress=total?Math.round(ps.reduce((s,p)=>s+Number(p.progress||0),0)/total):0;
let rows=ps.map(p=>{
let q=p.qcFindings||[],ts=(data.tasks||[]).filter(t=>String(t.projectId||'')===String(p.id));
return`<tr><td>${esc(p.id)}</td><td>${esc(p.name)}</td><td>${esc(p.client||'-')}</td><td>${badge(p.status)}</td><td><b>${Number(p.progress||0)}%</b></td><td>${q.filter(x=>x.status!=='CLOSED').length}</td><td>${ts.filter(x=>!['DONE','CANCELLED'].includes(x.status)).length}</td><td>${date(p.targetFinish)}</td><td><a class="btn ghost small" href="#/projects/${p.id}">Buka</a></td></tr>`;
}).join('');
v.innerHTML=pageHead('Dashboard Project','Monitoring project secara keseluruhan: progress, QC, task, nilai kontrak dan target.')+
`<div class="stats">${stat('Total Project',total)}${stat('Project Aktif',active.length)}${stat('Project Selesai',completed.length,'success')}${stat('On Hold',hold.length,'warning')}${stat('Terlambat',late.length,'warning')}</div>
<div class="stats mt">${stat('Progress Rata-rata',avgProgress+'%')}${stat('Current Contract',money(contract))}${stat('Total Paid',money(paid),'success')}${stat('Outstanding',money(outstanding),'warning')}</div>
<div class="grid2 mt">
${card('QC Project',`<div class="grid2eq">${info('Total Temuan',findings.length)}${info('Open / Aktif',findings.filter(x=>x.status!=='CLOSED').length)}${info('Overdue',findings.filter(x=>x.status==='OVERDUE').length)}${info('Closed',findings.filter(x=>x.status==='CLOSED').length)}</div>`)}
${card('Task Project',`<div class="grid2eq">${info('Diberikan',tasks.filter(x=>['TO_DO','REVISION'].includes(x.status)).length)}${info('Dikerjakan',tasks.filter(x=>x.status==='ON_PROGRESS').length)}${info('Menunggu Review',tasks.filter(x=>x.status==='SUBMITTED').length)}${info('Selesai',tasks.filter(x=>x.status==='DONE').length)}</div>`)}
</div>
<div class="mt">${card('Monitoring Project',`<div class="table-wrap"><table class="table"><thead><tr><th>ID</th><th>Project</th><th>Client</th><th>Status</th><th>Progress</th><th>QC Aktif</th><th>Task Aktif</th><th>Target</th><th>Aksi</th></tr></thead><tbody>${rows||'<tr><td colspan="9"><div class="empty">Belum ada project.</div></td></tr>'}</tbody></table></div>`)}</div>`;
}
function projects(v){let can=canManageProject();v.innerHTML=pageHead('Semua Project','Satu project menjadi arsip digital lengkap untuk kontrak, pembayaran, dokumen, operasional, QC dan serah terima.',can?'<button class="btn primary" id="newProject">＋ Tambah Project</button>':'')+projectCards(visibleProjects());if($('#newProject'))$('#newProject').onclick=()=>projectFormModal()}
