function uploadProjectDocumentModal(p,b,preset=null){let fixed=!!preset;openModal(`Upload ${preset?.label||'Dokumen Lain'}`,`<form id="simpleDocForm"><div class="form-grid">${fixed?'':`<label class="field" style="grid-column:1/-1"><span>NAMA DOKUMEN</span><input class="input" name="type" placeholder="Contoh: Surat Pernyataan" required></label>`}<label class="field" style="grid-column:1/-1"><span>PILIH FILE</span><input type="file" class="input" name="file" accept=".pdf,.xlsx,.xls,.doc,.docx,.jpg,.jpeg,.png" required></label><label class="field"><span>TANGGAL DOKUMEN</span><input type="date" class="input" name="date" value="${TODAY}"></label></div><button class="btn primary" style="width:100%">Upload Dokumen</button></form>`,()=>{$('#simpleDocForm').onsubmit=async e=>{e.preventDefault();let fd=new FormData(e.target),file=e.target.file.files[0],type=fixed?preset.type:String(fd.get('type')||'').trim(),category=fixed?preset.category:'OTHER';if(!file||!type)return;const btn=e.target.querySelector('button');btn.disabled=true;btn.textContent='Mengunggah...';try{let old=p.documents.filter(d=>d.type===type&&d.status==='FINAL');let version=(p.documents.filter(d=>d.type===type).reduce((m,d)=>Math.max(m,Number(d.version||0)),0)||0)+1,up=await uploadFile(file,'DOCUMENT',p.id);old.forEach(d=>d.status='SUPERSEDED');p.documents.push({id:uid('DOC'),category,type,name:up.name,fileId:up.id,status:'FINAL',version,date:fd.get('date')||TODAY});addProjectActivity(p,currentActor(),`${type} diupload.`);addAudit(currentActor(),'DOCUMENT',p.id,'UPLOAD',`${type} v${version}`);await save();closeModal();projectDocument(p,b)}catch(err){alert(err.message||'Upload gagal.');btn.disabled=false;btn.textContent='Upload Dokumen'}}})}
function editProjectDocumentModal(p,b,d){openModal(`Edit ${esc(d.type)}`,`<form id="editDocForm"><div class="form-grid">${d.category==='OTHER'?`<label class="field" style="grid-column:1/-1"><span>NAMA DOKUMEN</span><input class="input" name="type" value="${esc(d.type)}" required></label>`:''}<label class="field"><span>TANGGAL DOKUMEN</span><input type="date" class="input" name="date" value="${d.date||TODAY}"></label><label class="field" style="grid-column:1/-1"><span>GANTI FILE (OPSIONAL)</span><input type="file" class="input" name="file" accept=".pdf,.xlsx,.xls,.doc,.docx,.jpg,.jpeg,.png"></label></div><button class="btn primary" style="width:100%">Simpan Perubahan</button></form>`,()=>{$('#editDocForm').onsubmit=async e=>{e.preventDefault();let fd=new FormData(e.target),file=e.target.file.files[0],oldFile=d.fileId;try{if(d.category==='OTHER')d.type=String(fd.get('type')||d.type).trim();d.date=fd.get('date')||d.date;if(file){let up=await uploadFile(file,'DOCUMENT',p.id);d.fileId=up.id;d.name=up.name;d.version=Number(d.version||1)+1;if(oldFile)try{await removeFile(oldFile)}catch{}}addProjectActivity(p,currentActor(),`${d.type} diperbarui.`);addAudit(currentActor(),'DOCUMENT',d.id,'UPDATE',d.type);await save();closeModal();projectDocument(p,b)}catch(err){alert(err.message||'Gagal menyimpan dokumen.')}}})}
function projectDocument(p,b){let canEdit=['HEAD_BU','MANAGER_OPERASIONAL','ADMIN_GENERAL','SUPER_ADMIN'].includes(session.role),docs=p.documents.filter(d=>d.status!=='SUPERSEDED'&&d.name);b.innerHTML=pageHeadInline('Dokumen Project','Pilih jenis dokumen. Jika dokumen sudah tersedia, tekan kartunya untuk langsung membuka file.',canEdit?'<button class="btn ghost" id="addOtherDoc">＋ Dokumen Lain</button>':'')+`<div class="doc-choice-grid">${documentPresets.map(x=>{let d=[...p.documents].reverse().find(d=>d.type===x.type&&d.status==='FINAL'&&d.fileId);return `<div class="doc-choice-card ${d?'ready':''}"><button class="doc-choice-main" data-doc="${x.key}" data-file="${d?.fileId||''}"><span class="doc-choice-icon">${d?'✓':'＋'}</span><b>${esc(x.label)}</b><small>${d?'Tekan untuk buka dokumen':'Belum ada • tekan untuk upload'}</small></button>${d&&canEdit?`<button class="btn ghost small docChoiceEdit" data-id="${d.id}">Edit / Ganti</button>`:''}</div>`}).join('')}</div><div class="card mt"><div class="card-head"><h3>Semua Dokumen Project</h3><span class="small muted">${docs.length} dokumen aktif</span></div><div class="card-body"><div class="stack">${docs.map(d=>`<div class="doc-item doc-row"><div class="doc-main"><div class="doc-icon">▤</div><div><b>${esc(d.type)}</b><div class="tiny muted">${date(d.date)} • ${esc(d.name||'')}</div></div></div><div class="action-row">${d.fileId?`<a class="btn ghost small" target="_blank" href="${fileUrl(d.fileId)}">Buka</a>`:''}${canEdit?`<button class="btn ghost small editDoc" data-id="${d.id}">Edit</button><button class="btn danger small delDoc" data-id="${d.id}">Hapus</button>`:''}</div></div>`).join('')||'<div class="empty">Belum ada dokumen. Pilih jenis dokumen di atas.</div>'}</div></div></div>`;$$('.doc-choice-main').forEach(btn=>btn.onclick=()=>{if(btn.dataset.file)window.open(fileUrl(btn.dataset.file),'_blank');else if(canEdit)uploadProjectDocumentModal(p,b,documentPresets.find(x=>x.key===btn.dataset.doc))});$$('.docChoiceEdit').forEach(btn=>btn.onclick=()=>{let d=p.documents.find(x=>x.id===btn.dataset.id);if(d)editProjectDocumentModal(p,b,d)});if($('#addOtherDoc'))$('#addOtherDoc').onclick=()=>uploadProjectDocumentModal(p,b,null);$$('.editDoc').forEach(btn=>btn.onclick=()=>{let d=p.documents.find(x=>x.id===btn.dataset.id);if(d)editProjectDocumentModal(p,b,d)});$$('.delDoc').forEach(btn=>btn.onclick=async()=>{let d=p.documents.find(x=>x.id===btn.dataset.id);if(!d||!confirm(`Hapus dokumen ${d.type}?`))return;try{if(d.fileId)await removeFile(d.fileId);p.documents=p.documents.filter(x=>x.id!==d.id);addProjectActivity(p,currentActor(),`${d.type} dihapus.`);addAudit(currentActor(),'DOCUMENT',d.id,'DELETE',d.type);await save();projectDocument(p,b)}catch(err){alert(err.message||'Gagal menghapus dokumen.')}})}
function projectOperation(p,b){let canUpdate=['HEAD_BU','MANAGER_OPERASIONAL','SUPER_ADMIN'].includes(session.role);b.innerHTML=pageHeadInline('Operasional','Atur jadwal, target selesai, PIC dan progress proyek.',canUpdate?'<button class="btn ghost" id="editSchedule">✎ Edit Jadwal Project</button>':'')+`${card('Progress & Jadwal',`<div class="split"><span class="small">Progress Aktual</span><b id="progText">${p.progress}%</b></div>${canUpdate?`<input id="prog" type="range" min="0" max="100" value="${p.progress}" style="width:100%;margin-top:15px;accent-color:#2b6cb5">`:`<div class="progress mt"><div style="width:${p.progress}%"></div></div>`}<div class="grid2eq mt">${info('Status Operasional',badge(p.status))}${info('Tanggal Mulai',date(p.startDate))}${info('Target Selesai',date(p.targetFinish))}${info('PIC Operasional',`${esc(p.ops||'-')}<div class="tiny muted">${esc(userById(p.opsUserId)?.email||'')}</div>`)}${info('PIC QC',`${esc(p.qc||'-')}<div class="tiny muted">${esc(userById(p.qcUserId)?.email||'')}</div>`)}${info('Persetujuan Mulai',p.started?badge('APPROVED'):badge('PENDING'))}</div><div class="notice warn mt">Progress 100% belum otomatis menyelesaikan project. Tetap diperlukan QC selesai, BAST Final, dan persetujuan penyelesaian.</div>`)}`;if($('#editSchedule'))$('#editSchedule').onclick=()=>openModal('Edit Jadwal Project',`<form id="scheduleForm"><div class="form-grid"><label class="field"><span>TANGGAL MULAI</span><input type="date" class="input" name="startDate" value="${p.startDate||''}"></label><label class="field"><span>TARGET SELESAI</span><input type="date" class="input" name="targetFinish" value="${p.targetFinish||''}" required></label><label class="field"><span>PIC OPERASIONAL</span><select class="input" name="opsUserId">${userOptions(p.opsUserId||userByName(p.ops)?.id||'', ['MANAGER_OPERASIONAL','HEAD_BU','ADMIN_GENERAL'])}</select></label><label class="field"><span>PIC QC</span><select class="input" name="qcUserId">${userOptions(p.qcUserId||userByName(p.qc)?.id||'', ['MANAGER_QC','QC_TEKNIS'])}</select></label></div><button class="btn primary" style="width:100%">Simpan Jadwal</button></form>`,()=>{$('#scheduleForm').onsubmit=async e=>{e.preventDefault();let x=Object.fromEntries(new FormData(e.target)),ou=userById(x.opsUserId),qu=userById(x.qcUserId);p.startDate=x.startDate;p.targetFinish=x.targetFinish;p.opsUserId=x.opsUserId||'';p.ops=ou?.name||'';p.qcUserId=x.qcUserId||'';p.qc=qu?.name||'';addProjectActivity(p,currentActor(),`Jadwal project diperbarui. Target selesai ${date(p.targetFinish)}.`);addAudit(currentActor(),'PROJECT',p.id,'SCHEDULE_UPDATE',`Target ${p.targetFinish}`);await save();closeModal();projectOperation(p,b)}});if($('#prog'))$('#prog').onchange=async e=>{p.progress=+e.target.value;p.status=p.progress>=100?'HANDOVER':p.progress>=90?'FINISHING':p.progress>0?'RUNNING':'PREPARATION';$('#progText').textContent=p.progress+'%';addProjectActivity(p,currentActor(),`Progress diubah menjadi ${p.progress}%.`);await save()}}
function progressReportModal(p,b,kind,edit=null){let daily=kind==='DAILY',r=edit||{};openModal(`${edit?'Edit':'Tambah'} Laporan ${daily?'Harian':'Mingguan'}`,`<form id="progressReportForm"><div class="form-grid">${daily?`<label class="field"><span>TANGGAL</span><input type="date" class="input" name="date" value="${r.date||TODAY}" required></label>`:`<label class="field"><span>PERIODE MULAI</span><input type="date" class="input" name="start" value="${r.start||TODAY}" required></label><label class="field"><span>PERIODE SELESAI</span><input type="date" class="input" name="end" value="${r.end||TODAY}" required></label>`}<label class="field"><span>PROGRESS AKTUAL (%)</span><input type="number" min="0" max="100" class="input" name="progress" value="${Number(r.progress??p.progress)}" required></label>${daily?'':`<label class="field"><span>TARGET PROGRESS (%)</span><input type="number" min="0" max="100" class="input" name="targetProgress" value="${Number(r.targetProgress??p.progress)}"></label>`}<label class="field" style="grid-column:1/-1"><span>URAIAN PEKERJAAN / PROGRESS</span><textarea class="input" name="activities" rows="4" required>${esc(r.activities||'')}</textarea></label><label class="field" style="grid-column:1/-1"><span>KENDALA / CATATAN</span><textarea class="input" name="issues" rows="3">${esc(r.issues||'')}</textarea></label><label class="field" style="grid-column:1/-1"><span>RENCANA SELANJUTNYA</span><textarea class="input" name="nextPlan" rows="3">${esc(r.nextPlan||'')}</textarea></label><label class="field"><span>${edit?'FOTO PROGRESS (OPSIONAL)':'FOTO PROGRESS (OPSIONAL)'}</span><input type="file" class="input" name="file" accept="image/*" multiple></label><label class="field check-field"><span>PUBLIKASIKAN KE CLIENT</span><select class="input" name="published"><option value="1" ${r.published!==false?'selected':''}>Ya</option><option value="0" ${r.published===false?'selected':''}>Tidak</option></select></label></div><button class="btn primary" style="width:100%">Simpan Laporan</button></form>`,()=>{$('#progressReportForm').onsubmit=async e=>{e.preventDefault();let fd=new FormData(e.target),files=[...(e.target.file?.files||[])],arr=daily?p.progressDaily:p.progressWeekly,oldFile=r.fileId;try{if(files.length<3&&!edit)throw new Error('Minimal upload 3 foto progress.');let uploads=[];for(const file of files){uploads.push(await uploadFile(file,daily?'PROGRESS_DAILY':'PROGRESS_WEEKLY',p.id))}let up=uploads[0]||null,val={progress:Number(fd.get('progress')||0),activities:fd.get('activities'),issues:fd.get('issues'),nextPlan:fd.get('nextPlan'),published:fd.get('published')==='1',updatedBy:currentActor(),updatedAt:nowIso()};if(daily)val.date=fd.get('date');else{val.start=fd.get('start');val.end=fd.get('end');val.targetProgress=Number(fd.get('targetProgress')||0)}if(edit){Object.assign(r,val);if(uploads.length){r.fileId=uploads[0].id;r.fileName=uploads[0].name;r.photos=uploads.map(x=>({id:x.id,name:x.name}))}if(oldFile&&uploads.length)try{await removeFile(oldFile)}catch{}}else arr.unshift({id:uid(daily?'DPR':'WPR'),...val,fileId:up?.id||'',fileName:up?.name||'',photos:uploads.map(x=>({id:x.id,name:x.name})),createdBy:currentActor(),createdAt:nowIso()});p.progress=Math.max(Number(p.progress||0),Number(val.progress||0));addProjectActivity(p,currentActor(),`Laporan ${daily?'harian':'mingguan'} progress ${val.progress}% disimpan.`);addAudit(currentActor(),'PROGRESS_REPORT',p.id,edit?'UPDATE':'CREATE',daily?'Harian':'Mingguan');await save();closeModal();projectProgressReports(p,b)}catch(err){alert(err.message||'Gagal menyimpan laporan.')}}})}
function projectProgressReports(p,b){let canEdit=['HEAD_BU','MANAGER_OPERASIONAL','ADMIN_GENERAL','SUPER_ADMIN'].includes(session.role),daily=p.progressDaily||[],weekly=p.progressWeekly||[];b.innerHTML=pageHeadInline('Laporan Progress','Laporan harian dan mingguan yang dapat dipublikasikan langsung ke Portal Client.',canEdit?'<button class="btn primary" id="addDaily">＋ Laporan Harian</button> <button class="btn ghost" id="addWeekly">＋ Laporan Mingguan</button>':'')+`<div class="grid2"><div>${card('Laporan Harian',daily.map(r=>`<div class="report-item"><div class="split"><div><b>${date(r.date)} • ${r.progress}%</b><div class="tiny muted">${r.published!==false?'Tampil di Portal Client':'Internal saja'} • ${esc(r.createdBy||r.updatedBy||'-')}</div></div>${badge(r.published!==false?'PUBLISHED':'INTERNAL')}</div><div class="small report-text">${esc(r.activities||'-')}</div><div class="action-row">${(r.photos?.length||r.fileId)?`<div class="progress-photo-preview">${(r.photos||[{id:r.fileId,name:r.fileName}]).map(f=>`<img class="progress-photo-thumb" src="${fileUrl(f.id||f.fileId)}" alt="Foto Progress" loading="lazy" onclick="window.open(this.src, "_blank")">`).join('')}<a class="btn ghost small" target="_blank" href="${fileUrl((r.photos?.[0]?.id)||r.fileId)}">Buka Foto</a></div>`:''}${canEdit?`<button class="btn ghost small editProgress" data-kind="DAILY" data-id="${r.id}">Edit</button><button class="btn danger small delProgress" data-kind="DAILY" data-id="${r.id}">Hapus</button>`:''}</div></div>`).join('')||'<div class="empty">Belum ada laporan harian.</div>')}</div><div>${card('Laporan Mingguan',weekly.map(r=>`<div class="report-item"><div class="split"><div><b>${date(r.start)} – ${date(r.end)} • ${r.progress}%</b><div class="tiny muted">Target ${r.targetProgress||0}% • ${r.published!==false?'Tampil di Portal Client':'Internal saja'}</div></div>${badge(r.published!==false?'PUBLISHED':'INTERNAL')}</div><div class="small report-text">${esc(r.activities||'-')}</div><div class="action-row">${(r.photos?.length||r.fileId)?`<div class="progress-photo-preview">${(r.photos||[{id:r.fileId,name:r.fileName}]).map(f=>`<img class="progress-photo-thumb" src="${fileUrl(f.id||f.fileId)}" alt="Foto Progress" loading="lazy" onclick="window.open(this.src, "_blank")">`).join('')}<a class="btn ghost small" target="_blank" href="${fileUrl((r.photos?.[0]?.id)||r.fileId)}">Buka Foto</a></div>`:''}${canEdit?`<button class="btn ghost small editProgress" data-kind="WEEKLY" data-id="${r.id}">Edit</button><button class="btn danger small delProgress" data-kind="WEEKLY" data-id="${r.id}">Hapus</button>`:''}</div></div>`).join('')||'<div class="empty">Belum ada laporan mingguan.</div>')}</div></div>`;if($('#addDaily'))$('#addDaily').onclick=()=>progressReportModal(p,b,'DAILY');if($('#addWeekly'))$('#addWeekly').onclick=()=>progressReportModal(p,b,'WEEKLY');$$('.editProgress').forEach(btn=>btn.onclick=()=>{let arr=btn.dataset.kind==='DAILY'?p.progressDaily:p.progressWeekly,r=arr.find(x=>x.id===btn.dataset.id);if(r)progressReportModal(p,b,btn.dataset.kind,r)});$$('.delProgress').forEach(btn=>btn.onclick=async()=>{let arr=btn.dataset.kind==='DAILY'?p.progressDaily:p.progressWeekly,r=arr.find(x=>x.id===btn.dataset.id);if(!r||!confirm('Hapus laporan progress ini?'))return;if(r.fileId)try{await removeFile(r.fileId)}catch{}if(btn.dataset.kind==='DAILY')p.progressDaily=p.progressDaily.filter(x=>x.id!==r.id);else p.progressWeekly=p.progressWeekly.filter(x=>x.id!==r.id);await save();projectProgressReports(p,b)})}

function projectQc(p,b){b.innerHTML=pageHeadInline('QC / IC Project','Inspection → Finding → Corrective Action → Verification → Closed.')+`<div class="grid2">${card('Inspection',p.inspections.map(i=>`<div class="doc-item"><div><b>${i.id} • ${i.area}</b><div class="tiny muted">${i.category} • ${i.item} • ${date(i.date)}</div></div>${badge(i.result)}</div>`).join('')||'<div class="empty">Belum ada inspection.</div>')}${card('Findings',p.qcFindings.map(q=>`<div class="doc-item"><div><b>${q.id} • ${q.item}</b><div class="tiny muted">${q.area} • ${q.severity} • target ${date(q.target)}</div></div>${badge(q.status)}</div>`).join('')||'<div class="empty">Tidak ada finding.</div>')}</div>`}
function projectHandover(p,b){let dp=p.transactions.some(t=>t.type==='DP_PROYEK'&&t.status==='VERIFIED'),bast=hasFinalBast(p),qcReady=finalQcReady(p),canSubmit=['MANAGER_SALES','ADMIN_GENERAL','SALES_EXECUTIVE','HEAD_BU','SUPER_ADMIN'].includes(session.role),canReview=['MANAGER_OPERASIONAL','HEAD_BU','SUPER_ADMIN'].includes(session.role);b.innerHTML=pageHeadInline('Handover & Completion','Gerbang Pembangunan dan Selesai berasal dari event nyata, bukan status manual.')+`<div class="grid2">${card('Start Gate',`<div class="check"><span class="checkmark ${dp?'':'no'}">${dp?'✓':'×'}</span>DP Proyek VERIFIED</div><div class="check"><span class="checkmark ${p.contract.status==='SIGNED'?'':'no'}">${p.contract.status==='SIGNED'?'✓':'×'}</span>Contract SIGNED</div><div class="check"><span class="checkmark ${p.handover.status==='ACCEPTED'?'':'no'}">${p.handover.status==='ACCEPTED'?'✓':'×'}</span>Handover ACCEPTED</div><div class="check"><span class="checkmark ${p.started?'':'no'}">${p.started?'✓':'×'}</span>Project Start APPROVED</div>${['DRAFT','RETURNED'].includes(p.handover.status)&&canSubmit?`<button class="btn primary mt" id="submitH">Submit Handover</button>`:''}${p.handover.status==='SUBMITTED'&&canReview?`<div class="mt"><button class="btn primary" id="acceptH">Accept Handover</button> <button class="btn ghost" id="returnH">Return</button></div>`:''}${p.handover.status==='ACCEPTED'&&!p.started&&dp&&p.contract.status==='SIGNED'&&canReview?`<button class="btn primary mt" id="startP">Approve Project Start</button>`:''}`)}${card('Completion Gate',`<div class="check"><span class="checkmark ${p.progress>=100?'':'no'}">${p.progress>=100?'✓':'×'}</span>Progress 100%</div><div class="check"><span class="checkmark ${qcReady?'':'no'}">${qcReady?'✓':'×'}</span>Semua QC CLOSED</div><div class="check"><span class="checkmark ${bast?'':'no'}">${bast?'✓':'×'}</span>BAST FINAL</div><div class="check"><span class="checkmark ${p.completionApproved?'':'no'}">${p.completionApproved?'✓':'×'}</span>Completion APPROVED</div>${p.progress>=100&&qcReady&&!bast&&canReview?`<a class="btn ghost mt" href="#/projects/${p.id}/document">Upload BAST Final di Dokumen</a>`:''}${p.progress>=100&&qcReady&&bast&&!p.completionApproved&&canReview?`<button class="btn primary mt" id="completeP">Approve Completion</button>`:''}`)}</div>`;if($('#submitH'))$('#submitH').onclick=()=>{p.handover.status='SUBMITTED';p.handover.submittedAt=TODAY;addProjectActivity(p,currentActor(),'Handover SUBMITTED untuk review Manager Operasional.');addProjectChat(p,'System','Handover diajukan untuk review.',true);addAudit(currentActor(),'HANDOVER',p.id,'SUBMIT','Handover submitted');save();projectHandover(p,b)};if($('#acceptH'))$('#acceptH').onclick=()=>{p.handover.status='ACCEPTED';p.handover.reviewedAt=TODAY;addProjectActivity(p,currentActor(),'Handover ACCEPTED.');addProjectChat(p,'System','Handover ACCEPTED.',true);save();projectHandover(p,b)};if($('#returnH'))$('#returnH').onclick=()=>{p.handover.status='RETURNED';addProjectActivity(p,currentActor(),'Handover RETURNED untuk revisi.');addProjectChat(p,'System','Handover dikembalikan untuk revisi.',true);save();projectHandover(p,b)};if($('#startP'))$('#startP').onclick=()=>{p.started=true;p.startDate=p.startDate||TODAY;p.status='RUNNING';syncPipelineForProject(p);addProjectActivity(p,currentActor(),'Project Start APPROVED → Pembangunan.');addProjectChat(p,'System','Project Start APPROVED. Pipeline otomatis → Pembangunan.',true);addAudit(currentActor(),'PROJECT',p.id,'START_APPROVE','Project started');save();projectHandover(p,b)};if($('#completeP'))$('#completeP').onclick=()=>{p.completionApproved=true;p.status='COMPLETED';p.actualFinish=TODAY;syncPipelineForProject(p);addProjectActivity(p,currentActor(),'Project Completion APPROVED → SELESAI.');addProjectChat(p,'System','Completion APPROVED. Pipeline otomatis → Selesai.',true);addAudit(currentActor(),'PROJECT',p.id,'COMPLETION_APPROVE','Project completed');save();projectHandover(p,b)}}
function projectChat(p,b){b.innerHTML=pageHeadInline('Chat Internal Project','Diskusi internal melekat permanen pada Project dossier dan tidak tercampur dengan chat lead.')+chatBox(p.chat,'projectChatForm','Chat Project');let f=$('#projectChatForm');if(f)f.onsubmit=async e=>{e.preventDefault();let fd=new FormData(e.target),file=e.target.attachment.files[0],up=file?await uploadFile(file,'PROJECT_CHAT',p.id):null;addProjectChat(p,currentActor(),fd.get('message'),false,up?.name||'',up?.id||'');addProjectActivity(p,currentActor(),`Mengirim pesan di Chat Project${up?` + lampiran ${up.name}`:''}.`);addAudit(currentActor(),'PROJECT_CHAT',p.id,'MESSAGE','Pesan internal project');save();projectChat(p,b)}}
function projectActivity(p,b){b.innerHTML=card('Project Activity Log',`<div class="timeline">${p.activity.map(e=>`<div class="event"><div class="event-time">${e.at}</div><div class="event-text"><b>${e.actor}</b> — ${e.text}</div></div>`).join('')||'<div class="empty">Belum ada aktivitas.</div>'}</div>`)}

function correspondence(v){data.correspondence??=[];let rows=[...data.correspondence].sort((a,b)=>String(b.date||'').localeCompare(String(a.date||''))),canEdit=['ADMIN_GENERAL','HEAD_BU','SUPER_ADMIN'].includes(session.role);v.innerHTML=pageHead('Arsip Surat','Pengarsipan surat masuk dan surat keluar Rumsy dalam satu tempat.',canEdit?'<button class="btn primary" id="newLetter">＋ Tambah Surat</button>':'')+`<div class="stats">${stat('Surat Masuk',rows.filter(x=>x.direction==='MASUK').length)}${stat('Surat Keluar',rows.filter(x=>x.direction==='KELUAR').length)}${stat('Bulan Ini',rows.filter(x=>String(x.date||'').slice(0,7)===TODAY.slice(0,7)).length)}${stat('Total Arsip',rows.length)}</div><div class="card mt"><div class="card-body"><div class="filterbar"><label class="field grow"><span>CARI SURAT</span><input class="input" id="letterSearch" placeholder="Nomor surat, perihal, pengirim/penerima..."></label><label class="field"><span>JENIS</span><select class="input" id="letterType"><option value="">Semua</option><option value="MASUK">Surat Masuk</option><option value="KELUAR">Surat Keluar</option></select></label></div></div><div class="table-wrap"><table class="table"><thead><tr><th>Jenis</th><th>Tanggal</th><th>Nomor Surat</th><th>Dari / Kepada</th><th>Perihal</th><th>Project</th><th>File</th><th>Aksi</th></tr></thead><tbody id="letterRows"></tbody></table></div></div>`;
function draw(){let q=($('#letterSearch')?.value||'').toLowerCase(),t=$('#letterType')?.value||'',a=rows.filter(x=>(!t||x.direction===t)&&(!q||[x.number,x.party,x.subject,x.projectId,x.notes].some(y=>String(y||'').toLowerCase().includes(q))));$('#letterRows').innerHTML=a.map(x=>`<tr><td>${x.direction==='MASUK'?badge('SURAT MASUK'):badge('SURAT KELUAR')}</td><td>${date(x.date)}</td><td><b>${esc(x.number)}</b></td><td>${esc(x.party)}</td><td>${esc(x.subject)}${x.notes?`<div class="tiny muted">${esc(x.notes)}</div>`:''}</td><td>${x.projectId?`<a class="link" href="#/projects/${x.projectId}">${x.projectId}</a>`:'-'}</td><td>${x.fileId?`<a class="btn ghost small" target="_blank" href="${fileUrl(x.fileId)}">Lihat</a>`:'-'}</td><td>${canEdit?`<div class="action-row"><button class="btn ghost small editLetter" data-id="${x.id}">Edit</button><button class="btn danger small delLetter" data-id="${x.id}">Hapus</button></div>`:'-'}</td></tr>`).join('')||'<tr><td colspan="8" class="empty">Belum ada arsip surat.</td></tr>';wire()}
function modal(x=null){let e=x||{};openModal(x?'Edit Arsip Surat':'Tambah Arsip Surat',`<form id="letterForm"><div class="form-grid"><label class="field"><span>JENIS SURAT</span><select class="input" name="direction"><option value="MASUK" ${e.direction==='MASUK'?'selected':''}>Surat Masuk</option><option value="KELUAR" ${e.direction==='KELUAR'?'selected':''}>Surat Keluar</option></select></label><label class="field"><span>TANGGAL SURAT</span><input type="date" class="input" name="date" value="${e.date||TODAY}" required></label><label class="field"><span>NOMOR SURAT</span><input class="input" name="number" value="${esc(e.number||'')}" required></label><label class="field"><span>DARI / KEPADA</span><input class="input" name="party" value="${esc(e.party||'')}" required></label><label class="field" style="grid-column:1/-1"><span>PERIHAL</span><input class="input" name="subject" value="${esc(e.subject||'')}" required></label><label class="field"><span>PROJECT (OPSIONAL)</span><select class="input" name="projectId"><option value="">- Tidak terkait project -</option>${data.projects.map(p=>`<option value="${p.id}" ${e.projectId===p.id?'selected':''}>${p.id} • ${esc(p.client)}</option>`).join('')}</select></label><label class="field"><span>${x?'GANTI FILE (OPSIONAL)':'UPLOAD FILE'}</span><input type="file" class="input" name="file" accept=".pdf,.doc,.docx,.jpg,.jpeg,.png" ${x?'':'required'}></label><label class="field" style="grid-column:1/-1"><span>KETERANGAN</span><textarea class="input" name="notes" rows="3">${esc(e.notes||'')}</textarea></label></div><button class="btn primary" style="width:100%">Simpan Arsip Surat</button></form>`,()=>{$('#letterForm').onsubmit=async ev=>{ev.preventDefault();let fd=new FormData(ev.target),file=ev.target.file.files[0],old=e.fileId;try{let up=file?await uploadFile(file,'CORRESPONDENCE',e.id||'GENERAL'):null;let val={direction:fd.get('direction'),date:fd.get('date'),number:fd.get('number'),party:fd.get('party'),subject:fd.get('subject'),projectId:fd.get('projectId'),notes:fd.get('notes')};if(x){Object.assign(e,val);if(up){e.fileId=up.id;e.fileName=up.name;if(old)try{await removeFile(old)}catch{}}e.updatedBy=currentActor()}else{data.correspondence.unshift({id:uid('LTR'),...val,fileId:up?.id||'',fileName:up?.name||'',createdBy:currentActor(),createdAt:nowLabel()})}addAudit(currentActor(),'CORRESPONDENCE',x?e.id:'NEW',x?'UPDATE':'CREATE',`${val.direction} ${val.number}`);await save();closeModal();correspondence(v)}catch(err){alert(err.message||'Gagal menyimpan surat.')}}})}
function wire(){$$('.editLetter').forEach(btn=>btn.onclick=()=>modal(data.correspondence.find(x=>x.id===btn.dataset.id)));$$('.delLetter').forEach(btn=>btn.onclick=async()=>{let x=data.correspondence.find(y=>y.id===btn.dataset.id);if(!x||!confirm(`Hapus arsip surat ${x.number}?`))return;try{if(x.fileId)await removeFile(x.fileId);data.correspondence=data.correspondence.filter(y=>y.id!==x.id);addAudit(currentActor(),'CORRESPONDENCE',x.id,'DELETE',x.number);await save();correspondence(v)}catch(err){alert(err.message||'Gagal menghapus surat.')}})}
if($('#newLetter'))$('#newLetter').onclick=()=>modal();$('#letterSearch').oninput=draw;$('#letterType').onchange=draw;draw()}

function financeVerification(v){let rows=allTransactions().filter(t=>t.status==='PENDING_VERIFICATION');v.innerHTML=pageHead('Payment Verification','Hanya Finance/Super Admin yang dapat Verify/Reject. Upload bukti oleh Sales/Admin tetap Pending hingga diverifikasi.')+`<div class="stats">${stat('Pending',rows.length,'warning')}${stat('Pending Amount',money(rows.reduce((s,t)=>s+t.amount,0)))}${stat('Verified',allTransactions().filter(t=>t.status==='VERIFIED').length,'success')}${stat('Rejected',allTransactions().filter(t=>t.status==='REJECTED').length,'danger')}</div><div class="mt">${card('Queue',`<div class="table-wrap"><table class="table"><thead><tr><th>Project</th><th>Client</th><th>Payment</th><th>Amount</th><th>Bukti</th><th>Aksi</th></tr></thead><tbody>${rows.map(t=>`<tr><td><a class="link" href="#/projects/${t.projectId}/transaction">${t.projectId}</a></td><td>${t.client}</td><td>${t.label}</td><td class="mono"><b>${money(t.amount)}</b></td><td>${t.proofName}</td><td><a class="btn primary small" href="#/projects/${t.projectId}/transaction">Review</a></td></tr>`).join('')||'<tr><td colspan="6" class="empty">Tidak ada payment pending.</td></tr>'}</tbody></table></div>`)}</div>`}
function financeSchedule(v){let rows=visibleProjects().flatMap(p=>p.installments.map(i=>({p,i,paid:installmentPaid(p,i),status:installmentStatus(p,i)})));v.innerHTML=pageHead('Payment Schedule','Jadwal cicilan lintas project dengan status otomatis.')+card('Schedule',`<div class="table-wrap"><table class="table"><thead><tr><th>Project</th><th>Client</th><th>Installment</th><th>Due</th><th>Amount</th><th>Paid</th><th>Balance</th><th>Status</th></tr></thead><tbody>${rows.map(x=>`<tr><td><a class="link" href="#/projects/${x.p.id}/installment">${x.p.id}</a></td><td>${x.p.client}</td><td>${x.i.seq}</td><td>${date(x.i.due)}</td><td class="mono">${money(x.i.dueAmount)}</td><td class="mono">${money(x.paid)}</td><td class="mono">${money(Math.max(0,x.i.dueAmount-x.paid))}</td><td>${badge(x.status)}</td></tr>`).join('')}</tbody></table></div>`)}
function financeLedger(v){let rows=allTransactions();v.innerHTML=pageHead('Transaction Ledger','Semua payment record terhubung ke Project ID dan bukti.')+card('Ledger',`<div class="table-wrap"><table class="table"><thead><tr><th>ID</th><th>Project</th><th>Client</th><th>Date</th><th>Type</th><th>Amount</th><th>Proof</th><th>Status</th></tr></thead><tbody>${rows.map(t=>`<tr><td class="mono">${t.id}</td><td><a class="link" href="#/projects/${t.projectId}/transaction">${t.projectId}</a></td><td>${t.client}</td><td>${date(t.date)}</td><td>${t.label}</td><td class="mono">${money(t.amount)}</td><td>${t.proofName}</td><td>${badge(t.status)}</td></tr>`).join('')}</tbody></table></div>`)}
function financeOutstanding(v){let ps=data.projects.map(p=>({p,value:currentContract(p),paid:verifiedPaid(p),out:currentContract(p)-verifiedPaid(p)}));v.innerHTML=pageHead('Outstanding','Outstanding dihitung hanya dari VERIFIED payment.')+`<div class="stats">${stat('Current Contract',money(ps.reduce((s,x)=>s+x.value,0)))}${stat('Verified Paid',money(ps.reduce((s,x)=>s+x.paid,0)),'success')}${stat('Outstanding',money(ps.reduce((s,x)=>s+x.out,0)),'warning')}${stat('Overdue Installment',ps.reduce((s,x)=>s+x.p.installments.filter(i=>installmentStatus(x.p,i)==='OVERDUE').length,0),'danger')}</div><div class="mt">${card('Outstanding per Project',`<div class="table-wrap"><table class="table"><thead><tr><th>Project</th><th>Client</th><th>Current Contract</th><th>Paid</th><th>Outstanding</th></tr></thead><tbody>${ps.map(x=>`<tr><td><a class="link" href="#/projects/${x.p.id}">${x.p.id}</a></td><td>${x.p.client}</td><td class="mono">${money(x.value)}</td><td class="mono success">${money(x.paid)}</td><td class="mono warning"><b>${money(x.out)}</b></td></tr>`).join('')}</tbody></table></div>`)}</div>`}

function qc(v){let q=allFindings();v.innerHTML=pageHead('QC / IC Dashboard','QC Sipil & Interior terhubung ke Project ID.')+`<div class="stats five">${stat('Inspection',allInspections().length)}${stat('Open',q.filter(x=>x.status==='OPEN').length)}${stat('Major/Critical',q.filter(x=>['MAJOR','CRITICAL'].includes(x.severity)).length,'warning')}${stat('Overdue',q.filter(x=>x.status==='OVERDUE').length,'danger')}${stat('Waiting Verify',q.filter(x=>x.status==='WAITING_VERIFICATION').length)}</div><div class="mt">${findingTable(q)}</div>`}
function findingTable(q,actions=false){return card('Finding Register',`<div class="table-wrap"><table class="table"><thead><tr><th>Finding</th><th>Project</th><th>Area / Item</th><th>Severity</th><th>PIC</th><th>Target</th><th>Status</th>${actions?'<th>Aksi</th>':''}</tr></thead><tbody>${q.map(x=>`<tr><td><b>${x.id}</b></td><td><a class="link" href="#/projects/${x.projectId}/qc">${x.projectId}</a></td><td>${x.area}<div class="tiny muted">${x.item}</div></td><td>${badge(x.severity)}</td><td>${x.pic}</td><td>${date(x.target)}</td><td>${badge(x.status)}</td>${actions?`<td>${x.status==='WAITING_VERIFICATION'?`<button class="btn primary small qVerify" data-p="${x.projectId}" data-id="${x.id}">Verify</button>`:x.status==='OPEN'||x.status==='OVERDUE'?`<button class="btn ghost small qCorrect" data-p="${x.projectId}" data-id="${x.id}">Corrective</button>`:'-'}</td>`:''}</tr>`).join('')}</tbody></table></div>`)}
function qcInspection(v){let rows=allInspections();v.innerHTML=pageHead('QC Inspection','Buat inspection, pilih PASS atau buat Finding.','<button class="btn primary" id="newInsp">＋ Inspection</button>')+card('Inspection Register',`<div class="table-wrap"><table class="table"><thead><tr><th>ID</th><th>Project</th><th>Date</th><th>Category</th><th>Area</th><th>Work Item</th><th>Inspector</th><th>Result</th></tr></thead><tbody>${rows.map(i=>`<tr><td>${i.id}</td><td><a class="link" href="#/projects/${i.projectId}/qc">${i.projectId}</a></td><td>${date(i.date)}</td><td>${i.category}</td><td>${i.area}</td><td>${i.item}</td><td>${i.inspector}</td><td>${badge(i.result)}</td></tr>`).join('')}</tbody></table></div>`);$('#newInsp').onclick=()=>openModal('Buat QC Inspection',`<form id="inspForm"><div class="form-grid"><label class="field"><span>PROJECT</span><select class="input" name="projectId">${data.projects.map(p=>`<option value="${p.id}">${p.id} • ${p.client}</option>`).join('')}</select></label><label class="field"><span>DATE</span><input type="date" class="input" name="date" value="${TODAY}"></label><label class="field"><span>CATEGORY</span><select class="input" name="category"><option>SIPIL</option><option>INTERIOR</option></select></label><label class="field"><span>AREA</span><input class="input" name="area" required></label><label class="field"><span>WORK ITEM</span><input class="input" name="item" required></label><label class="field"><span>RESULT</span><select class="input" name="result"><option>PASS</option><option>FINDING_CREATED</option></select></label></div><button class="btn primary" style="width:100%">Simpan Inspection</button></form>`,()=>{$('#inspForm').onsubmit=e=>{e.preventDefault();let x=Object.fromEntries(new FormData(e.target)),p=projectById(x.projectId),i={id:uid('INSP'),date:x.date,category:x.category,area:x.area,item:x.item,result:x.result,inspector:'QC Teknis'};p.inspections.unshift(i);if(x.result==='FINDING_CREATED')p.qcFindings.unshift({id:uid('QC'),inspectionId:i.id,category:x.category,area:x.area,item:x.item,severity:'MINOR',description:'Finding baru dari inspection.',pic:'Manager Operasional',target:'2026-08-13',status:'OPEN',beforeName:'',afterName:'',corrective:''});save();closeModal();qcInspection(v)}})}
function qcFindings(v){let q=allFindings();v.innerHTML=pageHead('QC Findings','Finding memiliki corrective action dan verification.')+findingTable(q,true);wireQcActions(v)}
function wireQcActions(v){$$('.qCorrect').forEach(btn=>btn.onclick=()=>{let p=projectById(btn.dataset.p),q=p.qcFindings.find(x=>x.id===btn.dataset.id);openModal('Submit Corrective Action',`<form id="corrForm"><label class="field"><span>PERBAIKAN</span><textarea class="input" name="corrective" required></textarea></label><label class="field"><span>FOTO AFTER</span><input type="file" class="input" name="after"></label><button class="btn primary" style="width:100%">Submit → Waiting Verification</button></form>`);setTimeout(()=>{$('#corrForm').onsubmit=async e=>{e.preventDefault();let fd=new FormData(e.target),file=e.target.after.files[0],up=file?await uploadFile(file,'QC_CORRECTIVE',p.id):null;q.corrective=fd.get('corrective');q.afterName=up?.name||'';q.afterFileId=up?.id||'';q.status='WAITING_VERIFICATION';save();closeModal();qcFindings(v)}},0)});$$('.qVerify').forEach(btn=>btn.onclick=()=>{let p=projectById(btn.dataset.p),q=p.qcFindings.find(x=>x.id===btn.dataset.id);openModal('QC Verification',`<div class="notice info"><b>Corrective:</b> ${esc(q.corrective||'-')}<br><b>After:</b> ${esc(q.afterName||'-')}</div><div class="split" style="margin-top:14px"><button class="btn ghost" id="qReturn">Return to On Progress</button><button class="btn primary" id="qClose">Verify → Closed</button></div>`);setTimeout(()=>{$('#qClose').onclick=()=>{q.status='CLOSED';addAudit('QC Teknis','QC_FINDING',q.id,'CLOSE','Corrective action verified');save();closeModal();qcFindings(v)};$('#qReturn').onclick=()=>{q.status='ON_PROGRESS';save();closeModal();qcFindings(v)}},0)})}
function qcCorrective(v){let q=allFindings().filter(x=>['OPEN','OVERDUE','ON_PROGRESS','WAITING_VERIFICATION'].includes(x.status));v.innerHTML=pageHead('Corrective Action','Worklist temuan yang belum Closed.')+findingTable(q,true);wireQcActions(v)}
function qcEscalation(v){v.innerHTML=pageHead('QC Escalation — Confidential','Akses khusus Manager QC dan Super Admin.','<button class="btn primary" id="newEsc">＋ Escalate to Super Admin</button>')+`<div class="stack">${data.escalations.map(e=>`<div class="approval-card"><div class="top"><div><b>${e.subject}</b><div class="tiny muted">${e.projectId} • Finding ${e.finding}</div></div>${badge(e.status)}</div><div class="notice warn" style="margin-top:10px">CONFIDENTIAL • ${esc(e.notes)}</div>${session.role==='SUPER_ADMIN'&&!e.reviewedAt?`<button class="btn primary small reviewEsc" data-id="${e.id}" style="margin-top:10px">Tandai Ditinjau</button>`:''}</div>`).join('')}</div>`;$('#newEsc').onclick=()=>openModal('Escalate to Super Admin',`<form id="escForm"><label class="field"><span>PROJECT</span><select class="input" name="projectId">${data.projects.map(p=>`<option>${p.id}</option>`).join('')}</select></label><label class="field"><span>SUBJECT</span><input class="input" name="subject" required></label><label class="field"><span>FINDING</span><input class="input" name="finding"></label><label class="field"><span>NOTES</span><textarea class="input" name="notes" required></textarea></label><button class="btn primary" style="width:100%">Submit Confidential</button></form>`,()=>{$('#escForm').onsubmit=e=>{e.preventDefault();let x=Object.fromEntries(new FormData(e.target));data.escalations.unshift({id:uid('ESC'),...x,confidential:true,status:'SUBMITTED',submittedAt:TODAY,reviewedAt:''});save();closeModal();qcEscalation(v)}});$$('.reviewEsc').forEach(btn=>btn.onclick=()=>{let e=data.escalations.find(x=>x.id===btn.dataset.id);e.reviewedAt=TODAY;e.status='REVIEWED';save();qcEscalation(v)})}

function rmsNormalizeTaskPIC(value){
if(Array.isArray(value))return value.filter(Boolean);
if(value==null||value==='')return[];
return String(value).split(',').map(x=>x.trim()).filter(Boolean);
}
function rmsTaskPICUsers(t){
return rmsNormalizeTaskPIC(t?.picUserIds||t?.picUserId||t?.pic).map(userById).filter(Boolean);
}
function rmsTaskIsPIC(t){
return rmsTaskPICUsers(t).some(u=>String(u.id)===String(session.id));
}
function rmsTaskIsReviewer(t){
return String(t?.reviewerUserId||'')===String(session.id);
}
function rmsTaskStatusLabel(s){
return({TO_DO:'DIBERIKAN',ON_PROGRESS:'DIKERJAKAN',SUBMITTED:'MENUNGGU REVIEW',REVISION:'DIKEMBALIKAN',DONE:'SELESAI',CANCELLED:'BATAL'}[s]||'DIBERIKAN');
}
function tasks(v){
let canManage=['HEAD_BU','MANAGER_OPERASIONAL','MANAGER_SALES','MANAGER_QC','ADMIN_GENERAL','SUPER_ADMIN'].includes(session.role);
let all=data.tasks||[];
let waiting=all.filter(t=>rmsTaskIsPIC(t)&&(t.status==='TO_DO'||t.status==='REVISION')).length;
let review=all.filter(t=>rmsTaskIsReviewer(t)&&t.status==='SUBMITTED').length;
let cols=[{key:'TO_DO',title:'DIBERIKAN'},{key:'ON_PROGRESS',title:'DIKERJAKAN'},{key:'SUBMITTED',title:'MENUNGGU REVIEW'},{key:'DONE',title:'SELESAI'},{key:'CANCELLED',title:'BATAL'}];
function card(t){
let pics=rmsTaskPICUsers(t).map(u=>u.name).join(', ')||String(t.pic||'-');
let action='';
if((t.status==='TO_DO'||t.status==='REVISION')&&rmsTaskIsPIC(t))action=`<button class="btn primary small startTask" data-id="${t.id}">▶ Mulai Task</button>`;
if(t.status==='ON_PROGRESS'&&rmsTaskIsPIC(t))action=`<button class="btn primary small submitTask" data-id="${t.id}">✓ Ajukan Selesai</button>`;
if(t.status==='SUBMITTED'&&rmsTaskIsReviewer(t))action=`<button class="btn primary small approveTask" data-id="${t.id}">✓ Approve</button><button class="btn danger small reviseTask" data-id="${t.id}">↩ Kembalikan</button>`;
return`<div class="task-kanban-card" data-id="${t.id}">
<div class="split">${badge(t.priority)} ${badge(rmsTaskStatusLabel(t.status))}</div>
<h3>${esc(t.title)}</h3>
<div class="small">${esc(t.description||'-')}</div>
<div class="task-mini"><b>PIC</b><br>${esc(pics)}</div>
<div class="task-mini"><b>Atasan / Reviewer</b><br>${esc(t.reviewerName||'-')}</div>
<div class="task-mini"><b>Target</b><br>${date(t.due)}</div>
${t.reviewNote?`<div class="notice warn" style="margin-top:8px"><b>Catatan review:</b> ${esc(t.reviewNote)}</div>`:''}
<div style="display:flex;gap:6px;flex-wrap:wrap;margin-top:10px">${action}${canManage&&t.status!=='DONE'&&t.status!=='CANCELLED'?`<button class="btn ghost small editTask" data-id="${t.id}">Edit</button>`:''}${canManage&&(t.status==='TO_DO'||t.status==='REVISION'||t.status==='ON_PROGRESS')?`<button class="btn danger small deleteTask" data-id="${t.id}">Hapus</button>`:''}</div>
</div>`;
}
v.innerHTML=pageHead('Tasks','Workflow: Diberikan → Dikerjakan → Menunggu Review → Selesai.','<button class="btn primary" id="newTask">＋ Task</button>')+
`${waiting?`<div class="notice info" style="margin-bottom:12px">🔔 <b>${waiting} task</b> menunggu Anda. Tekan <b>Mulai Task</b> untuk memulai.</div>`:''}${review?`<div class="notice warn" style="margin-bottom:12px">🔔 <b>${review} task</b> menunggu review Anda.</div>`:''}<div class="kanban-board">${cols.map(c=>`<div class="kanban-col" data-status="${c.key}"><div class="kanban-title">${c.title}</div><div class="kanban-drop">${all.filter(t=>t.status===c.key).map(card).join('')||'<div class="empty">Kosong</div>'}</div></div>`).join('')}</div>`;
$('#newTask').onclick=()=>taskModal();
$$('.editTask').forEach(b=>b.onclick=()=>{let t=all.find(x=>x.id===b.dataset.id);if(t)taskModal(t)});
$$('.deleteTask').forEach(b=>b.onclick=async()=>{
let t=all.find(x=>x.id===b.dataset.id);
if(!t||!canManage)return;
if(!(t.status==='TO_DO'||t.status==='REVISION'||t.status==='ON_PROGRESS'))return;
if(!confirm('Hapus task ini?'))return;
data.tasks=(data.tasks||[]).filter(x=>String(x.id)!==String(t.id));
if(typeof addAudit==='function')addAudit(currentActor(),'TASK',t.id,'DELETE','Task dihapus.');
await save();
tasks(v);
});
$$('.startTask').forEach(b=>b.onclick=async()=>{let t=all.find(x=>x.id===b.dataset.id);if(!t||!rmsTaskIsPIC(t))return;t.status='ON_PROGRESS';t.startedAt=new Date().toISOString();t.updatedAt=new Date().toISOString();await save();tasks(v)});
$$('.submitTask').forEach(b=>b.onclick=async()=>{let t=all.find(x=>x.id===b.dataset.id);if(!t||!rmsTaskIsPIC(t))return;t.status='SUBMITTED';t.submittedAt=new Date().toISOString();t.reviewNote='';t.updatedAt=new Date().toISOString();await save();if(t.reviewerUserId)await sendTaskEmail('SUBMITTED',t,t.reviewerUserId);tasks(v)});
$$('.approveTask').forEach(b=>b.onclick=async()=>{let t=all.find(x=>x.id===b.dataset.id);if(!t||!rmsTaskIsReviewer(t))return;t.status='DONE';t.completedAt=new Date().toISOString();t.reviewNote='Disetujui oleh '+currentActor();t.updatedAt=new Date().toISOString();await save();for(let u of rmsTaskPICUsers(t))await sendTaskEmail('APPROVED',t,u.id);tasks(v)});
$$('.reviseTask').forEach(b=>b.onclick=()=>openModal('Kembalikan Task',`<form id="revTaskForm"><label class="field"><span>CATATAN PERBAIKAN</span><textarea class="input" name="note" required></textarea></label><button class="btn danger" style="width:100%">Kembalikan ke PIC</button></form>`,()=>{$('#revTaskForm').onsubmit=async e=>{e.preventDefault();let t=all.find(x=>x.id===b.dataset.id),note=new FormData(e.target).get('note');if(!t||!rmsTaskIsReviewer(t))return;t.status='REVISION';t.reviewNote=note;t.revisionCount=Number(t.revisionCount||0)+1;t.submittedAt='';t.updatedAt=new Date().toISOString();await save();for(let u of rmsTaskPICUsers(t))await sendTaskEmail('REVISION',t,u.id);closeModal();tasks(v)}}));
}
function taskModal(edit=null){
let t=edit||{},selected=rmsNormalizeTaskPIC(t.picUserIds||t.picUserId||t.pic),revSel=t.reviewerUserId||suggestedReviewer(selected[0])?.id||'';
let picOptions=userDirectory.map(u=>`<option value="${u.id}" ${selected.some(x=>String(x)===String(u.id))?'selected':''}>${esc(u.name)} • ${esc(roles[u.role]||u.role)} • ${esc(u.email)}</option>`).join('');
openModal(edit?'Edit Task':'Buat Task',`<form id="taskForm">
<label class="field"><span>JUDUL TUGAS</span><input class="input" name="title" value="${esc(t.title||'')}" required></label>
<label class="field"><span>DESKRIPSI TUGAS</span><textarea class="input" name="description" rows="3">${esc(t.description||'')}</textarea></label>
<div class="form-grid">
<label class="field"><span>PROJECT</span><select class="input" name="projectId"><option value="">- Tidak terkait project -</option>${data.projects.map(p=>`<option value="${p.id}" ${t.projectId===p.id?'selected':''}>${p.id} • ${esc(p.name)}</option>`).join('')}</select></label>
<label class="field"><span>PIC (BISA LEBIH DARI 1)</span><select class="input" id="taskPic" multiple size="5">${picOptions}</select><small class="tiny muted">Pilih beberapa PIC dengan Ctrl/Cmd + klik.</small></label>
<label class="field"><span>ATASAN / REVIEWER</span><select class="input" id="taskReviewer" name="reviewerUserId" required>${userOptions(revSel)}</select></label>
<label class="field"><span>TANGGAL MULAI</span><input type="date" class="input" name="startDate" value="${t.startDate||TODAY}" required></label>
<label class="field"><span>TARGET SELESAI</span><input type="date" class="input" name="due" value="${t.due||TODAY}" required></label>
<label class="field"><span>PRIORITY</span><select class="input" name="priority"><option value="LOW" ${t.priority==='LOW'?'selected':''}>LOW</option><option value="MEDIUM" ${!t.priority||t.priority==='MEDIUM'?'selected':''}>MEDIUM</option><option value="HIGH" ${t.priority==='HIGH'?'selected':''}>HIGH</option></select></label>
</div>
<div class="notice info">PIC menerima notifikasi saat task diberikan. Setelah selesai diajukan, task masuk ke reviewer untuk approval.</div>
<button class="btn primary" style="width:100%;margin-top:12px">Simpan Task</button></form>`,()=>{
let pic=$('#taskPic'),rev=$('#taskReviewer');
pic.onchange=()=>{let vals=[...pic.selectedOptions].map(o=>o.value),r=suggestedReviewer(vals[0]);if(r)rev.value=String(r.id)};
$('#taskForm').onsubmit=async e=>{
e.preventDefault();
let x=Object.fromEntries(new FormData(e.target)),picIds=[...pic.selectedOptions].map(o=>o.value).filter(Boolean),ru=userById(x.reviewerUserId);
if(!picIds.length||!ru)return alert('Minimal 1 PIC dan reviewer wajib dipilih.');
let pus=picIds.map(userById).filter(Boolean),oldIds=rmsNormalizeTaskPIC(t.picUserIds||t.picUserId||t.pic),isNew=!edit;
if(edit){
Object.assign(t,x,{picUserIds:picIds,picUserId:picIds[0],pic:pus.map(u=>u.name).join(', '),picEmail:pus.map(u=>u.email).join(', '),reviewerName:ru.name,reviewerEmail:ru.email});
}else{
t={id:uid('TSK'),...x,picUserIds:picIds,picUserId:picIds[0],pic:pus.map(u=>u.name).join(', '),picEmail:pus.map(u=>u.email).join(', '),reviewerName:ru.name,reviewerEmail:ru.email,creator:currentActor(),creatorUserId:session.id,status:'TO_DO',submittedAt:'',completedAt:'',reviewNote:'',revisionCount:0,emailStatus:'PENDING'};
data.tasks.unshift(t);
}
await save();
for(let pid of picIds)if(isNew||!oldIds.includes(pid))await sendTaskEmail('ASSIGNED',t,pid);
await save();closeModal();tasks($('#view'));
};
});
}

